[Bias] \label{rem:bias}
    It is easy to see that we can add bias -- that is not restricted to be non-negative -- to a monotone or input-convex neural network without breaking the properties guaranteed by Theorem \ref{thm:convexity_monotonicity}.
    For this insight let us briefly view bias as a shift of the activation function. Indeed, shifting the activation function neither breaks its convexity, its monotonicity nor its CPWL property.

\label{thm:shift_forward}
    For any $0 \leq l \leq L$ and any $c, \ a^{(+)}, \ a^{(-)} \in \RR ^ {d^{(l)}}$ we have
    \begin{align}
        g^{(l)}\!\left( \begin{bmatrix} a^{(+)} + c \\ a^{(-)} + c \end{bmatrix} \right)
            &= g^{(l)}\!\left( \begin{bmatrix} a^{(+)} \\ a^{(-)} \end{bmatrix} \right)
            + W_{\text{abs}}^{[l, \rightarrow]} \cdot c \\
        h^{(l)}\!\left( \begin{bmatrix} a^{(+)} + c \\ a^{(-)} + c \end{bmatrix} \right)
            &= h^{(l)}\!\left( \begin{bmatrix} a^{(+)} \\ a^{(-)} \end{bmatrix} \right)
            + W_{\text{abs}}^{[l, \rightarrow]} \cdot c.
    \end{align}

\label{thm:delta_pos_neg_connection}
    \begin{align}
        \delta^{(l,+,g)} &= W_{\text{abs}}^{[l, \rightarrow]} - \delta^{(l,-,g)}, \\
        \delta^{(l,+,h)} &= W_{\text{abs}}^{[l, \rightarrow]} - \delta^{(l,-,h)}
    \end{align}

\label{thm:closed_formula}
    \begin{align}
        \delta^{(l, g)}
            &= \frac{1}{2} \cdot \left[ \delta^{(l)}- \sum_{l \leq j < L} W_{\text{abs}}^{[j+1, \rightarrow]} \cdot \left( M^{(j+1,-)}W^{(j+1)} \right) \cdot \prod_{i = (j-1),\dots, l} W^{(i+1, x)} \right], \\
        \delta^{(l, h)}
            &= -\frac{1}{2} \cdot \left[ \delta^{(l)} + \sum_{l \leq j < L} W_{\text{abs}}^{[j+1, \rightarrow]} \cdot \left( M^{(j+1,-)}W^{(j+1)} \right) \cdot \prod_{i = (j-1),\dots, l} W^{(i+1, x)} \right].
    \end{align}

[Closed formulas for shifted saliency maps] \label{thm:closed_formula_shift}
    With $\overline{\alpha}_j \coloneqq \prod_{j+1 \leq i \leq L} \left( 1 - 2 \alpha^{(i)} \right)$ we obtain
    \begin{align}
        \delta_{\text{shift}}^g &= \frac{1}{2} \left[ \delta - \sum_{0 \leq j < L} \ \overline{\alpha}_j \frac{\partial Q[j+1]}{\partial x} \right], \label{eq:main_shifted_grad_pos}\\
        \delta_{\text{shift}}^h &= - \frac{1}{2} \left[ \delta + \sum_{0 \leq j < L} \ \overline{\alpha}_j  \frac{\partial Q[j+1]}{\partial x} \right]. \label{eq:main_shifted_grad_neg}
    \end{align}

\label{claim:sum_delta_shif}
        \begin{align}
            \delta_{\text{shift}}^{(l,+,g)} + \delta_{\text{shift}}^{(l,-,g)}
                = \prod_{l \leq j \leq L} \left( 1 - 2 \alpha^{(j)} \right) W_{\text{abs}}^{[l, \rightarrow]}.
        \end{align}

[Correctness] \label{thm:split_correct}
    For any $x^+, x^- \in \RR^{d^{(l)}}$
    \begin{align*}
        f^{(l)} \bigl( x^+ - x^- \bigr)
            = \bigl( g^{(l)} - h^{(l)} \bigr)
                \begin{bmatrix}
                    x^+ \\
                    x^-
                \end{bmatrix},
    \end{align*}

\label{thm:main_simplified}
    Any (residual) ReLU network $N$ containing linear, convolutional, maximum, matrix product and Hadamard product components can be split into two rank-$2$ monotone Maxout multiplication networks $N^+$ and $N^-$, that each calculate the maximum of a finite set of posynomials in the non-negative split input variables ($N = N^+ - N^-$).
    This construction gives an exact difference representation but does not generally give convex streams. For example, the positive monomial $xy$ is not convex on the positive orthant: it takes value $4$ at the midpoint of $(1,3)$ and $(3,1)$, whereas its value at both endpoints is $3$.

[Layerwise Recovery of the Original Activations]\label{thm:decomp-recovery}
For every layer $l$ and neuron $j$,
\begin{align}\label{eq:decomp-recovery-stop-mix}
    a_{\mathrm{stop},j}^{(l,+)} - a_{\mathrm{stop},j}^{(l,-)}
    =
    a_j^{(l)} = \relu\!\bigl(z_j^{(l)}\bigr).
\end{align}

[Path view on the Stopping Decomposition]\label{lem:parity-path}
Fix a feedforward ReLU network with weights $W^{(l)}$ (biases ignored; see remark at end of proof).
For neuron $j$ in layer $l \ge 1$, call a \emph{backward path} from $j$ to the input layer a list
of neuron indices
\begin{align}
    P = (P_l, P_{l-1}, \dots, P_0), \qquad P_l = j,
\end{align}
with $P_t$ indexing a neuron in layer $t$. The edges of $P$ use the weights $W^{(t)}_{P_{t-1},
    P_t}$ for $t = 1, \dots, l$. Define
\begin{align}
    w(P) \coloneqq \prod_{t=1}^{l} W^{(t)}_{P_{t-1}, P_t},
    \qquad
    |w|(P) \coloneqq \prod_{t=1}^{l} \bigl| W^{(t)}_{P_{t-1}, P_t} \bigr|,
\end{align}
the parity sign
\begin{align}
    \mathrm{sgn}(P) \in \{+,-\},
    \qquad
    \mathrm{sgn}(P) = + \iff \#\bigl\{t : W^{(t)}_{P_{t-1}, P_t} < 0\bigr\} \text{ is even,}
\end{align}
and the \emph{gate factor} (1 iff every gate on $P$ at intermediate layers $1,\dots,l-1$ is open)
\begin{align}
    G_{<l}(P) \coloneqq \prod_{t=1}^{l-1} \1\!\bigl[z_{P_t}^{(t)} > 0\bigr].
\end{align}
Then the decomposed pre-activations~\eqref{eq:split-pos}--\eqref{eq:split-neg} admit the path-sum
representation
\begin{align}
    z_j^{(l,+)} &= \sum_{P:\, P_l = j} G_{<l}(P)\, |w|(P)\, x_{P_0}^{\mathrm{sgn}(P)},
    \label{eq:parity-plus}\\
    z_j^{(l,-)} &= \sum_{P:\, P_l = j} G_{<l}(P)\, |w|(P)\, x_{P_0}^{\mathrm{sgn}(P)'}.
    \label{eq:parity-minus}
\end{align}

[Forward Equivalence for Stopping Game]\label{thm:forward-stopping}
The game admits a Subgame Perfect Nash Equilibrium (SPNE) where both players follow the same pure
strategy:
\begin{align} \label{eq:adf-spne-policy}
    \pi_q^{\star}\bigl(s_{j,q}^{(l, \mathrm{act})}\bigr) = \1\bigl[z_j^{(l)} > 0\bigr].
\end{align}
Under this equilibrium, the player-specific game values and the game values satisfy
\begin{align}\label{eq:adf-spne-values}
    \tilde{V}_p^{\pi^\star}\bigl(s_{j,q}^{(l, \mathrm{act})}\bigr) = a_{\mathrm{stop},j}^{(l, p \oplus
    q)},
    \qquad
    V_p^{\pi^\star}\bigl(s_{j,q}^{(l, \mathrm{act})}\bigr) = \xi_{p,q}\, a_j^{(l)}.
\end{align}

[Forward Equivalence for Addition]\label{prop:addition-equivalence}
The player-specific state value at the addition state equals the sum of the operand state values,
\begin{align}
    \tilde V_p^{\pi}\bigl(s_{z,q}^{\mathrm{add}}\bigr)
    \;=\;
    \tilde V_p^{\pi}(s_{x,q}) + \tilde V_p^{\pi}(s_{y,q}).
\end{align}
Consequently, if the operand states recover the Stopping-Decomposition activations---$\tilde
    V_p^{\pi^\star}(s_{x,q}) = x^{(p\oplus q)}$ and $\tilde V_p^{\pi^\star}(s_{y,q}) = y^{(p\oplus
    q)}$---then $\tilde V_p^{\pi^\star}(s_{z,q}^{\mathrm{add}}) = z^{(p\oplus q)}$, preserving the
forward equivalence of Theorem~\ref{thm:forward-stopping} across the residual sum.

[Max-Pooling Decision State]\label{def:maxpool-subgame}
For a pooled scalar output $z = \max\{x_1, \dots, x_m\}$, the \emph{pooling state} $s_{z,q}^{\max}$
has active player $q \in \{+, -\}$ and admissible action set $\mathcal{A}(s_{z,q}^{\max}) = \{1,
    \dots, m\}$ indexing the operand states $s_{x_1,q}, \dots, s_{x_m,q}$. Under action $k$, the
transition is deterministic,
\begin{align}
    \P\bigl(s_{x_k,q} \,\big|\, s_{z,q}^{\max}, k\bigr) \coloneqq 1,
\end{align}
with player $q$ retained at the chosen operand. The immediate payoff is $r_p(s_{z,q}^{\max}, k)
    \coloneqq 0$ for both $p \in \{+,-\}$, and the structural discount is $\gamma_{\mathrm{O}}
    \coloneqq 1$.

[Forward Equivalence for Max Pooling]\label{prop:maxpool-equivalence}
Assume the operand states recover the Stopping-Decomposition activations, $\tilde
    V_p^{\pi^\star}(s_{x_k,q}) = x_k^{(p\oplus q)}$ for all $k$, with non-negative operand activations
$x_k \ge 0$. Then at the SPNE of the subgame rooted at $s_{z,q}^{\max}$,
\begin{align}
    \tilde V_p^{\pi^\star}\bigl(s_{z,q}^{\max}\bigr) \;=\; z^{(p\oplus q)},
\end{align}
so the pooling state inherits the same Stopping-Decomposition identity as its winning operand and
the forward equivalence of Theorem~\ref{thm:forward-stopping} extends across the pooling node.

[Activation--Occupation Correspondence]\label{thm:deriv-occ}
Fix a neuron state $s = s_{j,q}^{(m, \mathrm{act})}$ and a layer $l \le m$ (for $l = 0$,
$s_{i,\cdot}^{(0,\mathrm{act})}$ denotes the terminal state $s_{i,\cdot}^{(0)}$). Under the
stop-at-tie-breaks equilibrium fixed by the boundary conventions of
Appendix~\ref{app:notation-identities} (uniquely fixing the SPNE at ReLU gates with $z = 0$ and at
max-pooling states with multiple maximizers), the discounted occupation measures exactly represent,
in a multi-trajectory ReLU network (e.g., a ResNet or a CNN with max pooling), the local
Stopping-Decomposition and scalar activation derivatives on open cells with nonzero ReLU preactivations and unique max-pooling winners. At ties, the same formulas represent the backward quantities computed using the selected gates and winners; they do not assert classical differentiability of the individual stopping streams, which can be discontinuous there:
\begin{enumerate}
    \item \textbf{Stopping-Decomposition Gradient:}
        \begin{align}
            \frac{\partial a_{\mathrm{stop},j}^{(m, p \oplus q)}}{\partial a_{\mathrm{stop},i}^{(l, k)}}
            \;=\;
            \Gamma_x\!\bigl(s_{i, p \oplus k}^{(l, \mathrm{act})} \bigm| s\bigr).
        \end{align}
    \item \textbf{Network Activation Gradient.} The ordinary-network gradient of $a_j^{(m)}$ with respect to
        the scalar activation $a_i^{(l)}$ is
        \begin{align}
            \frac{\partial a_j^{(m)}}{\partial a_i^{(l)}}
            \;=\;
            \xi_{q, +}\bigl(\Gamma_x(s_{i, +}^{(l, \mathrm{act})} \mid s) - \Gamma_x(s_{i, -}^{(l,
            \mathrm{act})} \mid s)\bigr).
        \end{align}
\end{enumerate}

[SPNE and Forward Equivalence of the Routing Game]\label{thm:routing-forward}
\leavevmode
\begin{description}
    \item[\textnormal{(i) \emph{SPNE existence for every $\tau > 0$ and $\varepsilon \ge 0$.}}]
        For every $\tau > 0$ and every $\varepsilon \ge 0$, the entropy-regularized two-player Routing Game
        of Definition~\ref{def:routing-recursion} (with linear-state entropy weight $\tau\,\mathcal{H}$ and
        outside-option stabilizer $\varepsilon$) admits a subgame-perfect Nash equilibrium
        (see~\eqref{eq:routing-spne-linear}--\eqref{eq:routing-spne-stop} in the proof for the explicit
        form of the equilibrium policy). We write $\cdot^\star$ for equilibrium quantities throughout.

    \item[\textnormal{(ii) \emph{Forward equivalence at the anchor $\tau=1$, $\varepsilon\geq 0$.}}]
        At $\tau=1$ and $\varepsilon \geq 0$, the equilibrium quantities recover the network forward pass:
        for every layer $l$, neuron $j$, player labels $p,q,r$, and stream sign $\kappa\in\{+,-\}$,
        \begin{align}
            V_r\bigl(s_{j,q,\kappa}^{(l, lin)}\bigr) &= \ell\bigl(\delta_{r,q} \, (\Sigma_j^{(l,\kappa)} +
            \varepsilon)\bigr), \label{eq:routing-forward-linear}\\
            Q_r\left( s_{j,p}^{(l, act)}, \text{continue} \right) &= \ell \left( \xi_{r,p} \cdot z^{(l)}_j
            \right), \label{eq:routing-forward-continue} \\
            V_r\bigl(s_{j,p}^{(l, act)}\bigr) &= \ell\bigl( \delta_{r,p}\ \cdot a_j^{(l)} \bigr),
            \label{eq:routing-forward-act}\\
            \pi_p^\star\bigl(s_{j,p}^{(l, act)}\bigr) &= \1[z_j^{(l)} > 0]. \label{eq:routing-forward-stop}
        \end{align}
\end{description}

[Recovery of Multi-Path $\alpha\beta$-\ac{LRP}]\label{thm:ab-recovery}
For every $\varepsilon \ge 0$ and every input with $f(x)=a_u^{(L)}>0$ (if $f(x)=0$ the root player
stops and $R^{(l)}=f(x)\Gamma^{(l)}=0$ trivially), under the stop-at-tie-breaks equilibrium
(Remark~\ref{rem:routing-spne-uniqueness}; ties at max-pooling states broken by the smallest index)
at the anchor temperature $\tau = 1$ and stabilizer $\varepsilon$, with the cumulative trajectory
discount~\eqref{eq:routing-discount} and the occupation measure $\Gamma_j^{(l)}$
from~\eqref{eq:routing-Gamma-pair}:
\begin{enumerate}
    \item \textbf{Linear Map.} The per-neuron difference $\Gamma^{(l)}_j$ of~\eqref{eq:routing-Gamma-pair}
        satisfies
        \begin{align}\label{eq:lrp-eps-recovery}
            \Gamma^{(l-1)}_i
            \;=\; \sum_j \left(
            \alpha \frac{[a_i^{(l-1)} W_{ij}^{(l)}]^+}{\varepsilon + \Sigma_j^{(l,+)}}
            -
            \beta \frac{[a_i^{(l-1)} W_{ij}^{(l)}]^-}{\varepsilon + \Sigma_j^{(l,-)}}
            \right) \Gamma^{(l)}_j.
        \end{align}
        Because~\eqref{eq:lrp-eps-recovery} and~\eqref{eq:lrp-eps-recursion} share their computational
        step, $\Gamma^{(l)}_j \cdot R_u^{(L)} = R^{(l)}_j$ at every layer; in particular $R^{(l)}_j =
            f(x)\,\Gamma^{(l)}_j$ for the seed $R^{(L)}_u = f(x)$. The same formula covers the fused input
        layer with $a^{(0)} = x$. At $\varepsilon = 0$ this reduces to the unstabilized
        $\alpha\beta$-\ac{LRP} redistribution (not conservative: bias nodes absorb relevance); at
        $\varepsilon > 0$ \ch{it is the $\alpha\beta$ rule with the stabilization convention adopted here,
        i.e.\ \eqref{eq:lrp-ab} with $\varepsilon$ added to each sign denominator separately.}
    \item \textbf{Residual Addition.} Let $z = x_{\mathrm{op}} + y_{\mathrm{op}}$ be an addition node with
        addition state $s^{\mathrm{add}}_{z,p}$ and operand states $s_{x_{\mathrm{op}},p},
            s_{y_{\mathrm{op}},p}$ as in Appendix~\ref{app:routing-skip}. For every player label $p\in\{+,-\}$,
        with the edge occupation $\Gamma_x(s\to s')\coloneqq\E_{\zeta\sim\Pi_x}\bigl[\sum_t
            d_{t+1}(\zeta)\1\{\zeta_t=s,\zeta_{t+1}=s'\}\bigr]$ (an operand's total occupation adds the edges
        from its other parents),
        \begin{align}
            \Gamma_x\!\bigl(s^{\mathrm{add}}_{z,p}\to s_{x_{\mathrm{op}},p}\bigr) \;=\;
            \tfrac12\,\Gamma_x\!\bigl(s^{\mathrm{add}}_{z,p}\bigr),
            \qquad
            \Gamma_x\!\bigl(s^{\mathrm{add}}_{z,p}\to s_{y_{\mathrm{op}},p}\bigr) \;=\;
            \tfrac12\,\Gamma_x\!\bigl(s^{\mathrm{add}}_{z,p}\bigr),
        \end{align}
        so the operand pair carries the full addition-state mass with no duplication.
    \item \textbf{Max Pooling.} For a pooled output $z = \max\{x_1,\dots,x_m\}$ with winner $k^\star$ and
        pooling state $s_{z,p}^{\max}$ (Appendix~\ref{app:routing-skip}), the deterministic
        value-maximizing transition concentrates all mass on the winner: for every player label $p \in
            \{+,-\}$,
        \begin{align}
            \Gamma_x\!\bigl(s^{\max}_{z,p}\to s_{x_{k^\star},p}\bigr) \;=\;
            \Gamma_x\!\bigl(s_{z,p}^{\max}\bigr),
            \qquad
            \Gamma_x\!\bigl(s^{\max}_{z,p}\to s_{x_{k},p}\bigr) \;=\; 0 \text{ for } k \neq k^\star.
        \end{align}
\end{enumerate}

[Legendre--Fenchel transform of KL divergence]\label{lem:kl-legendre-fenchel}
Let $\mathcal{X}$ be a finite set, $\bar\pi \in \Delta(\mathcal{X})$ a reference distribution with
full support on $\mathcal{X}$, and $r : \mathcal{X} \to \RR$ a real-valued payoff. The
KL-regularized linear maximization
\begin{align}\label{eq:kl-lf-objective}
    F(r;\bar\pi) \;\coloneqq\; \max_{\pi \in \Delta(\mathcal{X})}
    \Bigl\{ \E_\pi[r] \;-\; \mathrm{KL}(\pi \,\|\, \bar\pi) \Bigr\}
\end{align}
has the following optimizer and optimum:
\begin{align}\label{eq:kl-lf-optimizer}
    \pi_r^\star(x) \;=\; \frac{\bar\pi(x)\,\exp\!\bigl(r(x)\bigr)}{Z(r;\bar\pi)},
    \qquad
    F(r;\bar\pi) \;=\; \log Z(r;\bar\pi) \;=\; \log\!\sum_{x \in \mathcal{X}}
    \bar\pi(x)\,\exp\!\bigl(r(x)\bigr).
\end{align}

[Value-side optimal policy]\label{prop:attn-value-policy}
If $Z_{t,d}^\kappa > 0$, the unique optimizer of~\eqref{eq:attn-value-routing} is
\begin{align}\label{eq:attn-value-policy}
    \pi_{t,d,\kappa}^\star(k)
    \;=\;
    \frac{\bar\pi_t(k)\, \tilde{v}_{k,d}^\kappa}{Z_{t,d}^\kappa},
\end{align}
with active-player value $V_p(s_{(t,d),p,\kappa}^{(\mathrm{att},\,\mathrm{O},\,\mathrm{lin})}) =
    \ell(Z_{t,d}^\kappa)$ and inactive-player value
$V_{p'}(s_{(t,d),p,\kappa}^{(\mathrm{att},\,\mathrm{O},\,\mathrm{lin})}) = -\infty$ as in
Definition~\ref{def:routing-recursion}. If $Z_{t,d}^\kappa = 0$, no key contributes mass on stream
$\kappa$ and $V_p(s_{(t,d),p,\kappa}^{(\mathrm{att},\,\mathrm{O},\,\mathrm{lin})}) = -\infty$.

[$\alpha\beta$-\ac{LRP} recovery for attention]\label{thm:attn-ab-recovery}
For signed inputs $X$, under the SPNE of \S\ref{app:attention-state-space} with reference
$\bar\pi_t = A_{t,\cdot}$ and the trajectory discount of~\eqref{eq:routing-edge-discount}
restricted to the (sole) sign-oracle split at $s^{(\mathrm{att},\,\mathrm{O},\,\mathrm{act})}$, the
per-input-neuron player-difference $\Gamma^{X}_{k,e}$ from~\eqref{eq:attn-Gamma-X} satisfies
\begin{align}\label{eq:attn-ab-recovery}
    \Gamma^{X}_{k,e}
    \;=\;
    \sum_{t,d} \left(
    \alpha\, \frac{A_{t,k}\, [X_{k,e} W_{v,e,d}]^+}{Z_{t,d}^+}
    \;-\;
    \beta\, \frac{A_{t,k}\, [X_{k,e} W_{v,e,d}]^-}{Z_{t,d}^-}
    \right) \Gamma^{O}_{t,d},
\end{align}
where the per-output-entry input difference is
\begin{align}\label{eq:attn-Gamma-O}
    \Gamma^{O}_{t,d} \;\coloneqq\;
    \Gamma_x\!\bigl(s_{t,d,+}^{(\mathrm{att},\,\mathrm{O},\,\mathrm{act})}\bigr) \;-\;
    \Gamma_x\!\bigl(s_{t,d,-}^{(\mathrm{att},\,\mathrm{O},\,\mathrm{act})}\bigr),
\end{align}
with $\Gamma^{O}_{t,d} = R^{O}_{t,d}$ by inductive hypothesis from the surrounding recursion, for
the seed $R^{(L)}_u = 1$ (for the seed $f(x)$ every relevance equals $f(x)$ times the corresponding
$\Gamma$, as in Theorem~\ref{thm:ab-recovery}). The right-hand side is exactly the target
rule~\eqref{eq:attn-target-input}, hence $\Gamma^{X}_{k,e} = R^{X}_{k,e}$. Aggregating over $e$ and
the bias node at fixed $(k,d)$ collects the relevance routed through the Value entry $v_{k,d}$:
\begin{align}\label{eq:attn-Gamma-V-corollary}
    \Gamma^{\mathrm{val}}_{k,d}
    \;=\;
    \sum_t \left( \alpha\, \frac{A_{t,k}\, \tilde{v}_{k,d}^+}{Z_{t,d}^+} \;-\; \beta\, \frac{A_{t,k}\,
    \tilde{v}_{k,d}^-}{Z_{t,d}^-} \right) \Gamma^{O}_{t,d}
    \;=\; R^{\mathrm{val}}_{k,d},
\end{align}
recovering the per-Value-entry formula~\eqref{eq:attn-target-rule}.

[Probit dual of the soft gate]\label{lem:noisy-gate-dual}
For every $z\in\RR$, the regularized maximization
\begin{align}\label{eq:noisy-gate-objective}
    \max_{\pi \in [0,1]}\; \bigl\{\,\pi z \;+\; \mathcal{R}_\Phi(\pi)\,\bigr\}
\end{align}
admits the unique maximizer $\pi^\star = \Phi(z)$ and optimum value
\begin{align}\label{eq:noisy-gate-optimum}
    z\,\Phi(z) + \phi(z) \;=\; \E_{\eta\sim\mathcal{N}(0,1)}\!\bigl[\max(z+\eta,\,0)\bigr].
\end{align}

[Softplus gradient recovery]\label{thm:softplus-gradient}
Under the SPNE of Theorem~\ref{thm:softplus-forward} on the Softplus network with activation
$\mathrm{sp}_\theta$, the discounted occupation difference recovers the Softplus-network gradient
exactly as in Theorem~\ref{thm:deriv-occ}:
\begin{align}
    \frac{\partial a_j^{(m)}}{\partial a_i^{(l)}}
    \;=\;
    \xi_{q,+}\Bigl(\Gamma_x\bigl(s_{i,+}^{(l, \mathrm{act})} \bigm| s\bigr) -
    \Gamma_x\bigl(s_{i,-}^{(l, \mathrm{act})} \bigm| s\bigr)\Bigr),
    \qquad s = s_{j,q}^{(m, \mathrm{act})},
\end{align}
with $\Gamma_x$ now driven by $\Pi_x^\theta$.

[Chain rule]\label{lem:bc-chain-rule}
For every $l \in \{0, 1, \ldots, L\}$, the Bhattacharyya coefficient of the prefix distributions
factorizes along trajectories:
\begin{align}\label{eq:bc-chain-rule}
    \mathrm{BC}\!\bigl(\Pi^{(l)}_A,\, \Pi^{(l)}_B\bigr) \;=\; \sum_{(\zeta_L, \ldots, \zeta_l)}
    \mathbf{1}\{\zeta_L = s_0\} \prod_{k=l+1}^{L} \widetilde{T}^{(k)}(\zeta_k, \zeta_{k-1}).
\end{align}

[Monotonicity]\label{lem:bc-monotone}
Let $\mathrm{BC}^{(l)} \coloneqq \mathrm{BC}(\Pi^{(l)}_A, \Pi^{(l)}_B)$.  Then $\mathrm{BC}^{(l)}$
is monotonically non-increasing as $l$ decreases from $L$ to $0$:
\begin{align}
    1 \;=\; \mathrm{BC}^{(L)} \;\geq\; \mathrm{BC}^{(L-1)} \;\geq\; \cdots \;\geq\; \mathrm{BC}^{(0)}
    \;\geq\; 0.
\end{align}
Equivalently, the squared Hellinger distance $\mathrm{H}^{2}_{(l)} = 1 - \mathrm{BC}^{(l)}$ is
monotonically non-decreasing.

[Backward pass correctness]\label{lem:hellinger-backward-correctness}
Algorithm~\ref{alg:hellinger} computes $g^{(l)}$, hence $\mathrm{BC}^{(l)}$, $\mathrm{H}^{(l)}$,
and $\mathrm{H}^2(s)$ correctly for every $l$ and $s$.  In particular,
\begin{align}
    \sum_{s \in \mathcal{S}^{(0)}_+} \mathrm{H}^2(s) \;=\; \mathrm{H}^{2}_{(0)}.
\end{align}

[Per-pixel decomposition]\label{thm:per-pixel}
Let $\mathrm{H}^2 \coloneqq \mathrm{H}^2\!\bigl(\Pi^{(0)}_A,\, \Pi^{(0)}_B\bigr)$.  For $s \in
    \mathcal{S}^{(0)}_+$, define
\begin{align}\label{eq:per-pixel-h2}
    \mathrm{H}^2(s) \;\coloneqq\; \tfrac{1}{2}\bigl(m^{(0)}_A(s) + m^{(0)}_B(s)\bigr) \;-\; g^{(0)}(s),
\end{align}
where $g^{(0)}(s)$ is the cumulative $\widetilde{T}$-mass at $s$.  Then:
\begin{enumerate}
    \item[(i)] $\mathrm{H}^2(s) \geq 0$ for every $s \in \mathcal{S}^{(0)}_+$.
    \item[(ii)]
        \begin{align}\label{eq:per-pixel-sum}
            \mathrm{H}^2 \;=\; \sum_{s \in \mathcal{S}^{(0)}_+} \mathrm{H}^2(s).
        \end{align}
    \item[(iii)]
        \begin{align}\label{eq:ordinary-h2}
            \mathrm{H}^2_{\mathrm{ord}} \;\coloneqq\; \sum_{s \in \mathcal{S}^{(0)}} \mathrm{H}^2(s) \;=\;
            \mathrm{H}^2 - \mathrm{H}^2(\dagger)
        \end{align}
\end{enumerate}

[Conditioned-survival trajectory law and conditioned Hellinger distance]\label{thm:conditioned-survival}
Let $\mathsf{Surv} \coloneqq \{(\zeta_L,\ldots,\zeta_0) : \zeta_0 \in \mathcal{S}^{(0)}\}$ be the
event, in the trajectory space $\prod_{l=0}^{L} \mathcal{S}^{(l)}_+$, that the backward trajectory
ends in an ordinary input-layer state — equivalently, the event that the trajectory never enters
the cemetery~$\dagger$.  For each model $M \in \{A,B\}$ define the survival function
\begin{align}\label{eq:survival-function}
    \psi_M^{(l)}(s)
    \;\coloneqq\;
    \mathbb{P}_M(\mathsf{Surv} \mid \zeta_l = s),
    \qquad s \in \mathcal{S}^{(l)}_+, \;\; l \in \{0,\ldots,L\}.
\end{align}
Then:
\begin{enumerate}
    \item[(i)] The boundary and recursion are
        \begin{align}\label{eq:survival-boundary}
            \psi_M^{(0)}(s) = 1 \;\; \text{for } s \in \mathcal{S}^{(0)},
            \qquad
            \psi_M^{(0)}(\dagger) = 0,
        \end{align}
        and for every $l \ge 1$,
        \begin{align}\label{eq:survival-recursion}
            \psi_M^{(l)}(s)
            \;=\;
            \sum_{s' \in \mathcal{S}^{(l-1)}_+} T_M^{(l)}(s \to s')\, \psi_M^{(l-1)}(s')
            \;=\;
            \sum_{s' \in \mathcal{S}^{(l-1)}} T_M^{(l)}(s \to s')\, \psi_M^{(l-1)}(s').
        \end{align}
        In particular,
        \begin{align}\label{eq:survival-mass}
            Z_M \;\coloneqq\; \mathbb{P}_M(\mathsf{Surv}) \;=\; \psi_M^{(L)}(s_0) \;=\; \sum_{s \in
            \mathcal{S}^{(0)}} m_M^{(0)}(s) \;=\; 1 - m_M^{(0)}(\dagger).
        \end{align}
    \item[(ii)] Assume $Z_M > 0$.  For every ordinary state $s \in \mathcal{S}^{(l)}$ with $\psi_M^{(l)}(s) >
            0$, define the conditioned kernel on ordinary states by
        \begin{align}\label{eq:conditioned-kernel}
            T_{M,\mathrm{surv}}^{(l)}(s \to s')
            \;\coloneqq\;
            \frac{T_M^{(l)}(s \to s')\, \psi_M^{(l-1)}(s')}{\psi_M^{(l)}(s)},
            \qquad s' \in \mathcal{S}^{(l-1)}.
        \end{align}
        Then $T_{M,\mathrm{surv}}^{(l)}(s \to \cdot)$ is row-stochastic on $\mathcal{S}^{(l-1)}$, and the
        conditional trajectory distribution $\Pi_{M,\mathrm{surv}} \coloneqq \Pi_M(\,\cdot \mid
            \mathsf{Surv}\,)$ factorizes as the layered Markov law
        \begin{align}\label{eq:conditioned-path-measure}
            \Pi_{M,\mathrm{surv}}(\zeta_L,\ldots,\zeta_0)
            = \mathbf{1}\{\zeta_L = s_0\} \prod_{k=1}^{L} T_{M,\mathrm{surv}}^{(k)}(\zeta_k \to \zeta_{k-1}),
            \qquad (\zeta_L,\ldots,\zeta_0) \in \mathsf{Surv}.
        \end{align}
        Its layer-$l$ marginals satisfy
        \begin{align}\label{eq:conditioned-alpha}
            m_{M,\mathrm{surv}}^{(l)}(s)
            \;=\;
            \frac{m_M^{(l)}(s)\, \psi_M^{(l)}(s)}{Z_M},
            \qquad s \in \mathcal{S}^{(l)}.
        \end{align}
    \item[(iii)] Define the conditioned geometric-mean kernel
        \begin{align}\label{eq:conditioned-geom-kernel}
            \widetilde{T}_{\mathrm{surv}}^{(l)}(s,s')
            \coloneqq \sqrt{T_{A,\mathrm{surv}}^{(l)}(s \to s')\, T_{B,\mathrm{surv}}^{(l)}(s \to s')}
            = \frac{\widetilde{T}^{(l)}(s,s')\, \sqrt{\psi_A^{(l-1)}(s')\,
            \psi_B^{(l-1)}(s')}}{\sqrt{\psi_A^{(l)}(s)\, \psi_B^{(l)}(s)}}.
        \end{align}
        The Bhattacharyya coefficient of the conditioned trajectory laws is
        \begin{align}\label{eq:conditioned-bc-kernel}
            \mathrm{BC}\!\bigl(\Pi_{A,\mathrm{surv}}, \Pi_{B,\mathrm{surv}}\bigr)
            \;=\;
            \sum_{(\zeta_L,\ldots,\zeta_0) \in \mathsf{Surv}}
            \mathbf{1}\{\zeta_L = s_0\}
            \prod_{k=1}^{L} \widetilde{T}_{\mathrm{surv}}^{(k)}(\zeta_k, \zeta_{k-1}),
        \end{align}
        so it is computed by the same Hellinger pass (Algorithm~\ref{alg:hellinger}), but on the
        ordinary-state graph with the conditioned kernel.
    \item[(iv)] Let
        \begin{align}\label{eq:ordinary-bc}
            \mathrm{BC}_{\mathrm{ord}}^{(0)}
            \;\coloneqq\;
            \sum_{s \in \mathcal{S}^{(0)}} g^{(0)}(s)
            \;=\;
            \sum_{(\zeta_L,\ldots,\zeta_0) \in \mathsf{Surv}} \sqrt{\Pi_A(\zeta_L,\ldots,\zeta_0)\,
            \Pi_B(\zeta_L,\ldots,\zeta_0)}.
        \end{align}
        Then
        \begin{align}\label{eq:conditioned-bc-posthoc}
            \mathrm{BC}\!\bigl(\Pi_{A,\mathrm{surv}}, \Pi_{B,\mathrm{surv}}\bigr)
            \;=\;
            \frac{\mathrm{BC}_{\mathrm{ord}}^{(0)}}{\sqrt{Z_A Z_B}},
        \end{align}
        and the conditioned-survival Hellinger distance is
        \begin{align}\label{eq:conditioned-h2}
            \mathrm{H}_{\mathrm{surv}}^2
            \;\coloneqq\;
            \mathrm{H}^2\!\bigl(\Pi_{A,\mathrm{surv}}, \Pi_{B,\mathrm{surv}}\bigr)
            \;=\;
            1 - \frac{\mathrm{BC}_{\mathrm{ord}}^{(0)}}{\sqrt{Z_A Z_B}}.
        \end{align}
\end{enumerate}

[Randomization in the Stopping Game]\label{thm:rand-adf}
$\mathbb{E}_B\bigl[\mathrm{BC}^{(0)}_{\mathrm{ord}}(\Pi_A, \Pi_B)\bigr] \leq \eta^{N}$.  Hence, for
every $z > 0$, the conditioned-survival distance of Theorem~\ref{thm:conditioned-survival}
satisfies $\mathbb{E}_B\bigl[\mathrm{H}^2_{\mathrm{surv}}\,\1\{Z_A Z_B \geq z\}\bigr] \geq
    \mathbb{P}_B(Z_A Z_B \geq z) - \eta^{N}/\sqrt{z}$, while the plain distance is $\mathrm{H}^2 = 1 -
    \mathrm{BC}^{(0)}_{\mathrm{ord}} - g^{(0)}(\dagger)$.

[Feedforward \ac{relu} network]\label{def:ffn_relu}
Let $L \in \NN$ and let $d^{(0)}, d^{(1)}, \ldots, d^{(L)} \in \NN$ denote the \emph{layer widths}, with input dimension $d^{(0)}$ and output dimension $d^{(L)}$. A \emph{feedforward \ac{relu} network} of depth $L$ is given by weight matrices $\Wl{l} \in \RR^{d^{(l)} \times d^{(l-1)}}$ and bias vectors $b^{(l)} \in \RR^{d^{(l)}}$ for $l = 1, \ldots, L$. On an input $x \in \RR^{d^{(0)}}$ it computes the recursion
\begin{align}
	\actl{0} &\coloneqq x, \notag\\
	\preactl{l} &\coloneqq \Wl{l} \actl{l-1} + b^{(l)}, && l = 1, \ldots, L, \label{eq:forward_recursion}\\
	\actl{l} &\coloneqq \relu\bigl(\preactl{l}\bigr), && l = 1, \ldots, L-1, \notag
\end{align}
where $\relu(z) \coloneqq \max\{z, 0\}$ acts componentwise, and the output layer is affine, $\actl{L} \coloneqq \preactl{L}$. We call $\preactl{l}$ the \emph{pre-activation} and $\actl{l}$ the \emph{(post-)activation} of layer $l$, and denote the \emph{network function} by
\begin{equation}
	f \colon \RR^{d^{(0)}} \longrightarrow \RR^{d^{(L)}},
	\qquad
	f(x) \coloneqq \actl{L}.
	\label{eq:network_function}
\end{equation}
Layers $1, \ldots, L-1$ are the \emph{hidden layers}. Throughout we fix the boundary convention $\relu'(0) \coloneqq 0$, so that the gate indicator $\1\{\preactl{l}_i > 0\}$ returns $0$ at $\preactl{l}_i = 0$.

[Positive and negative parts]\label{def:posneg_parts}
For a scalar $u \in \RR$ we write $u^{+} \coloneqq \max\{u, 0\}$ and $u^{-} \coloneqq \max\{-u, 0\}$, so that $u = u^{+} - u^{-}$ and $\abs{u} = u^{+} + u^{-}$, with $u^+ u^- = 0$. For a matrix or vector $W$ and a sign label $\sigma \in \{+,-\}$, the \emph{entrywise part} $\posneg{W}{\sigma}$ is obtained by applying $u \mapsto u^{\sigma}$ to every entry. For the layer weights and biases of Definition~\ref{def:ffn_relu} we abbreviate
\begin{equation}
	\Wsig{l}{\sigma} \coloneqq \posneg{\Wl{l}}{\sigma},
	\qquad
	b^{(l,\sigma)} \coloneqq \posneg{b^{(l)}}{\sigma},
	\qquad \sigma \in \{+,-\},
	\label{eq:weight_split}
\end{equation}
so that $\Wl{l} = \Wsig{l}{+} - \Wsig{l}{-}$ and $\abs{\Wl{l}} = \Wsig{l}{+} + \Wsig{l}{-}$ entrywise, and both $\Wsig{l}{\sigma}$ are entrywise non-negative.

\label{obs:relu_is_cpwl}
Every feedforward \ac{relu} network represents a \ac{cpwl} function.
\hfill\LeanResult{obs:relu_is_cpwl}

[Monotone networks represent monotone functions]\label{prop:monotone_represents}
A monotone neural network represents a monotone function; each coordinate function is non-decreasing in every input variable.
\hfill\LeanResult{prop:monotone_represents}

[\acp{icnn} represent convex functions]\label{prop:icnn_convex}
An \ac{icnn} represents a convex function; each coordinate of every activation $\actl{l}$, $l \ge 1$, is a convex function of the input $x$.
\hfill\LeanResult{prop:icnn_convex}

[Maxout unit and Maxout network, \parencite{Goodfellow2013Maxout}]\label{def:maxout}
A \emph{rank-$k$ Maxout unit} with weights $w_1, \ldots, w_k \in \RR^{d}$ and biases $\beta_1, \ldots, \beta_k \in \RR$ computes
\begin{equation}
	x \longmapsto \maxout(x) \coloneqq \max_{j \in [k]} \bigl( w_j^{\top} x + \beta_j \bigr).
	\label{eq:maxout_unit}
\end{equation}
A \emph{rank-$k$ Maxout network} is a feedforward network whose neurons are rank-$k$ Maxout units; equivalently, layer $l$ carries $k$ weight matrices $W^{(l)}_1, \ldots, W^{(l)}_k$ and biases $b^{(l)}_1, \ldots, b^{(l)}_k$, and
\begin{equation}
	\actl{l}_i \coloneqq \max_{j \in [k]} \bigl( W^{(l)}_j \actl{l-1} + b^{(l)}_j \bigr)_i .
	\label{eq:maxout_layer}
\end{equation}

[\ac{relu} and max-pooling as Maxout]\label{obs:relu_maxout_special_case}
The \ac{relu} activation is the rank-$2$ Maxout unit with parameters $(w_1, \beta_1) = (w, \beta)$ and $(w_2, \beta_2) = (0, 0)$, since $\relu(w^\top x + \beta) = \max\{w^\top x + \beta,\, 0\}$. Max-pooling over a group $J$ of neurons is the rank-$\abs{J}$ Maxout unit whose $j$-th argument is the coordinate projection onto the $j$-th element of $J$. Every rank-$k$ Maxout unit is convex in its input and non-decreasing in each pre-activation argument $w_j^\top x + \beta_j$; hence Maxout qualifies as an admissible activation in Definitions~\ref{def:monotone_network} and \ref{def:icnn}.
\hfill\LeanResult{obs:relu_maxout_special_case}

[\acl{mdp}]\label{def:mdp}
A (finite) \emph{\acl{mdp}} (\acs{mdp}) \parencite{Puterman1994mdp,SuttonBarto2018rl} is a tuple $\mathcal{M} = (S, A, \P, R, \gamma)$ consisting of a finite state set $S$, a finite action set $A(s)$ for each $s \in S$, a \emph{transition kernel} $\P(s' \mid s, a) \ge 0$ with $\sum_{s'} \P(s' \mid s, a) = 1$, a bounded \emph{reward function} $R(s, a) \in \RR$, and a \emph{discount factor} $\gamma \in [0, 1)$. A \emph{(stationary) policy} is a map $\pi$ assigning to each state $s$ a probability distribution $\pi(\cdot \mid s)$ over $A(s)$; $\pi$ is \emph{pure} (deterministic) if each $\pi(\cdot \mid s)$ is a point mass. A policy induces, for every start state, a Markov chain on $S$ and hence a distribution over trajectories $(s_0, a_0, s_1, a_1, \ldots)$; the \emph{value function} of $\pi$ is the expected discounted return
\begin{equation}
	V^{\pi}(s) \coloneqq \E^{\pi}\Bigl[ \textstyle\sum_{t=0}^{\infty} \gamma^{t}\, R(s_t, a_t) \,\Big|\, s_0 = s \Bigr],
	\label{eq:mdp_value}
\end{equation}
and the \emph{optimal value function} is $V^{\star}(s) \coloneqq \max_{\pi} V^{\pi}(s)$.

[Bellman equations]\label{prop:bellman}
Let $\mathcal{M}$ be a finite \ac{mdp} with $\gamma \in [0,1)$. Then:
\begin{enumerate}
	\item $V^{\pi}$ is the unique solution of the linear system
	\begin{equation}
		V(s) = \sum_{a \in A(s)} \pi(a \mid s) \Bigl[ R(s,a) + \gamma \sum_{s'} \P(s' \mid s, a)\, V(s') \Bigr],
		\qquad s \in S.
		\label{eq:bellman_evaluation}
	\end{equation}
	\item $V^{\star}$ is the unique solution of the \emph{Bellman optimality equation}
	\begin{equation}
		V(s) = \max_{a \in A(s)} \Bigl\{ R(s, a) + \gamma \sum_{s'} \P(s' \mid s, a)\, V(s') \Bigr\},
		\qquad s \in S,
		\label{eq:bellman_optimality}
	\end{equation}
	and any pure policy $\polstar$ that selects, in every state, an action attaining the maximum in \eqref{eq:bellman_optimality} is optimal: $V^{\polstar} = V^{\star}$.
\end{enumerate}
\hfill\LeanResult{prop:bellman}

[State-dependent structural discounts]\label{rem:structural_discount}
The games of this thesis depart from Definition~\ref{def:mdp} in one respect: the discount is \emph{state-dependent}, $\gamma(s) \ge 0$, and may exceed $1$. Here discounts are not impatience parameters but \emph{structural} normalizers---for neuron $i$ in layer $l$ the absolute weight mass
\begin{equation}
	\gamma^{(l)}_i \coloneqq \sum_{j} \bigl( \Wsig{l}{+} + \Wsig{l}{-} \bigr)_{ij} = \sum_j \abs{\Wl{l}_{ij}},
	\label{eq:structural_discount}
\end{equation}
which restores the weight mass after row $i$ of $\abs{\Wl{l}}$ is normalized into transition probabilities. Contraction is then unavailable, but also unnecessary: all games are played on \emph{layered acyclic} graphs, so every trajectory is finite and all value functions are well-defined finite sums. Backward induction gives a unique value and the existence of optimal policies; policies need not be unique when actions tie. The two-player statement follows below.

[Shapley--Bellman optimality on layered games]\label{thm:shapley_bellman}
Let $\mathcal{G}$ be a finite zero-sum turn-based game whose transition graph is acyclic. Then $\mathcal{G}$ has a \emph{value}: there is a unique function $V^{\star} \colon S \to \RR$ satisfying the \emph{Shapley--Bellman optimality equations}
\begin{equation}
	V^{\star}(s) =
	\begin{cases}
		\displaystyle \max_{a \in A(s)} \Bigl\{ R(s,a) + \gamma(s) \sum_{s'} \P(s' \mid s, a)\, V^{\star}(s') \Bigr\}, & s \in S_{+}, \\[1.2em]
		\displaystyle \min_{a \in A(s)} \Bigl\{ R(s,a) + \gamma(s) \sum_{s'} \P(s' \mid s, a)\, V^{\star}(s') \Bigr\}, & s \in S_{-}, \\[1.2em]
		R(s), & s \in S_{\mathrm{ter}},
	\end{cases}
	\label{eq:shapley_bellman}
\end{equation}
and there exist pure stationary policies $\polstar = (\polstar_{+}, \polstar_{-})$, obtained by selecting maximizing respectively minimizing actions in \eqref{eq:shapley_bellman}, such that for all $s \in S$ and all policies $\pi_{+}, \pi_{-}$,
\begin{equation}
	V^{(\polstar_{+}, \pi_{-})}(s) \;\ge\; V^{\polstar}(s) = V^{\star}(s) \;\ge\; V^{(\pi_{+}, \polstar_{-})}(s).
	\label{eq:saddle_point}
\end{equation}
In particular, $\polstar$ is a Nash equilibrium of every subgame, i.e.\ a subgame perfect equilibrium.
\hfill\LeanResult{thm:shapley_bellman}

[ReLU Net Game, following \parencite{Gaubert2025}]\label{def:relu_net_game}
The \emph{ReLU Net Game} on the network $f$ at input $x$ is the zero-sum turn-based game with the following components.
\begin{itemize}
	\item \textbf{States.} For every hidden layer $l \in \{1, \ldots, L-1\}$, every neuron $i \in [d^{(l)}]$, and every turn label $q \in \{+,-\}$ there is an \emph{activation state} $s^{(l)}_{i,q}$, controlled by player $P^{q}$, so that $S_q = \bigl\{ s^{(l)}_{i,q} : l \in [L-1],\, i \in [d^{(l)}] \bigr\}$. For every input coordinate $k \in [d^{(0)}]$ and every $q \in \{+,-\}$ there is a \emph{terminal state} $s^{(0)}_{k,q}$, and there is one absorbing \emph{cemetery state} $\perp$ with zero payoff. Finally, there is a single \emph{output state} $s^{(L)}$ at the affine output neuron, at which no decision is taken.
	\item \textbf{Actions.} At every activation state the player in turn chooses an action from $\{\mathrm{stop}, \mathrm{cont}\}$. The output state has the single action $\mathrm{cont}$.
	\item \textbf{Transitions.} Stopping moves deterministically to the cemetery, $\P(\perp \mid s^{(l)}_{i,q}, \mathrm{stop}) = 1$. Continuation at $s^{(l)}_{i,q}$ moves one layer backward, to neuron $j$ of layer $l-1$ with probability proportional to the absolute weight, keeping the turn on positive weights and passing it to the opponent on negative weights:
	\begin{equation}
		\P\bigl( s^{(l-1)}_{j,r} \,\big|\, s^{(l)}_{i,q}, \mathrm{cont} \bigr)
		\coloneqq \frac{\Wsig{l}{q \oplus r}_{ij}}{\gamma^{(l)}_i},
		\qquad
		\gamma^{(l)}_i = \sum_{j} \bigl( \Wsig{l}{+} + \Wsig{l}{-} \bigr)_{ij},
		\label{eq:rng_kernel}
	\end{equation}
	where for $l = 1$ the successor $s^{(0)}_{j,r}$ is the corresponding terminal state. The output state transitions by the same rule \eqref{eq:rng_kernel} with $l = L$ and turn label $q = +$.
	\item \textbf{Payoffs and discounts.} Continuation at $s^{(l)}_{i,q}$ pays the signed bias $\xi_{q}\, b^{(l)}_i$; stopping pays $0$. A terminal state pays the signed input coordinate once, $R\bigl(s^{(0)}_{k,q}\bigr) \coloneqq \xi_{q}\, x_k$, and the game ends. The output state pays $b^{(L)}$ upon its forced continuation. The discount at every activation state and at the output state is the structural discount $\gamma\bigl(s^{(l)}_{i,q}\bigr) \coloneqq \gamma^{(l)}_i$ of \eqref{eq:structural_discount}.
\end{itemize}
Player $P^{+}$ maximizes and $P^{-}$ minimizes the expected discounted total payoff, as in Definition~\ref{def:turn_based_game}.

[Forward pass as game value, \parencite{Gaubert2025}]\label{thm:relu_net_game_value}
The ReLU Net Game of Definition~\ref{def:relu_net_game} admits the subgame perfect equilibrium $\polstar = (\polstar_{+}, \polstar_{-})$ in which both players use the same pure stopping rule,
\begin{equation}
	\polstar_{q}\bigl( s^{(l)}_{i,q} \bigr) = \mathrm{cont}
	\quad \Longleftrightarrow \quad
	\preactl{l}_i > 0,
	\label{eq:rng_equilibrium_policy}
\end{equation}
and the value function of the game evaluates the network:
\begin{equation}
	V^{\star}\bigl(s^{(l)}_{i,q}\bigr) = \xi_{q}\, \actl{l}_i
	\quad \text{for } l \in \{0, 1, \ldots, L-1\},
	\qquad
	V^{\star}\bigl(s^{(L)}\bigr) = f(x),
	\label{eq:rng_value_identity}
\end{equation}
where for $l = 0$ we read $\actl{0}_k = x_k$. The equilibrium is unique up to tie-breaking at neurons with $\preactl{l}_i = 0$, where both actions are optimal; the convention \eqref{eq:rng_equilibrium_policy} stops at ties, matching $\relu'(0) = 0$.
\hfill\LeanResult{thm:relu_net_game_value}

[Softplus networks from entropy regularization]\label{rem:softplus_game}
\textcite{Gaubert2025} also treat softplus networks, by \emph{regularizing} the stop/continue decision. Replace the hard choice at an activation state by a mixed policy $\nu \in \Delta(\{\mathrm{stop}, \mathrm{cont}\})$ rewarded with a Shannon-entropy bonus at temperature $\theta > 0$. By the Legendre--Fenchel identity for the entropy \parencite{BoydVandenberghe2004},
\begin{equation}
	\max_{\nu \in \Delta_n} \Bigl\{ \textstyle\sum_{i=1}^{n} \nu_i r_i + \theta\, \mathcal{H}(\nu) \Bigr\}
	= \theta \log \textstyle\sum_{i=1}^{n} e^{r_i / \theta},
	\qquad
	\mathcal{H}(\nu) = -\textstyle\sum_i \nu_i \log \nu_i,
	\label{eq:legendre_fenchel}
\end{equation}
with the Gibbs distribution $\nu^{\star}_i \propto e^{r_i/\theta}$ as unique maximizer, the regularized value at a state with continuation value $\preactl{l}_i$ (computed as in \eqref{eq:rng_cont_value}) becomes $\theta \log\bigl(1 + e^{\preactl{l}_i / \theta}\bigr)$---the softplus activation at temperature $\theta$---and the equilibrium policy continues with the sigmoid probability $\bigl(1 + e^{-\preactl{l}_i/\theta}\bigr)^{-1}$. The hard game of Definition~\ref{def:relu_net_game} is recovered in the limit $\theta \to 0$. Chapter~\ref{ch:game_theory} re-derives this mechanism from the regularized decompositions of Section~\ref{sec:regularized_decompositions} and reuses it at the routing states of the \ac{rg}, with the two temperatures $\theta$ (activation gates) and $\tau$ (routing) kept distinct.

[Max-plus and min-plus semirings]\label{def:maxplus_semiring}
The \emph{max-plus semiring} is the set $\RR_{\max} \coloneqq \RR \cup \{-\infty\}$ equipped with \emph{tropical addition} and \emph{tropical multiplication},
\begin{equation}
	u \oplus v \coloneqq \max\{u, v\},
	\qquad
	u \odot v \coloneqq u + v,
	\label{eq:tropical_operations}
\end{equation}
with additive neutral element $-\infty$ and multiplicative neutral element $0$. Both operations are associative and commutative, and $\odot$ distributes over $\oplus$; additive inverses do not exist, so $\RR_{\max}$ is a semiring but not a ring. The \emph{min-plus semiring} $\RR_{\min} \coloneqq \RR \cup \{+\infty\}$ is defined dually with $u \oplus' v \coloneqq \min\{u,v\}$; the map $u \mapsto -u$ is an isomorphism between the two, so every statement below has a min-plus counterpart.

[Tropical polynomials and rational functions]\label{def:tropical_polynomial}
A \emph{tropical monomial} in $d$ variables with exponent $\alpha \in \RR^{d}$ and coefficient $c \in \RR$ is the affine function $c \odot x_1^{\odot \alpha_1} \odot \cdots \odot x_d^{\odot \alpha_d} = c + \langle \alpha, x \rangle$. A \emph{tropical polynomial} with finite support $\mathcal{A} \subset \RR^{d}$ and coefficients $(c_{\alpha})_{\alpha \in \mathcal{A}}$, $c_\alpha \in \RR$, is the tropical sum of monomials,
\begin{equation}
	p(x) \;=\; \bigoplus_{\alpha \in \mathcal{A}} c_{\alpha} \odot x^{\odot \alpha}
	\;=\; \max_{\alpha \in \mathcal{A}} \bigl( c_{\alpha} + \langle \alpha, x \rangle \bigr).
	\label{eq:tropical_polynomial}
\end{equation}
A \emph{tropical rational function} is a tropical quotient of two tropical polynomials, $p \oslash q \coloneqq p - q$. In classical tropical geometry \parencite{MaclaganSturmfels2015tropical} the exponents are restricted to $\mathcal{A} \subset \NN^{d}$ or $\ZZ^{d}$; for neural networks, real exponents (network weights) are the natural setting, and all statements below hold verbatim in this generality.

[Tropical polynomials are the convex \ac{cpwl} functions]\label{obs:tropical_convex_cpwl}
A function $p \colon \RR^d \to \RR$ is a tropical polynomial \eqref{eq:tropical_polynomial} if and only if it is convex and \ac{cpwl}.
\hfill\LeanResult{obs:tropical_convex_cpwl}

[Newton polytope]\label{def:newton_polytope}
The \emph{Newton polytope} of a tropical polynomial $p$ with support $\mathcal{A}$ as in \eqref{eq:tropical_polynomial} is the convex hull of its exponent vectors,
\begin{equation}
	\operatorname{Newt}(p) \coloneqq \operatorname{conv}\bigl\{ \alpha : \alpha \in \mathcal{A} \bigr\} \subset \RR^{d}.
	\label{eq:newton_polytope}
\end{equation}
The \emph{lifted Newton polytope} additionally records the coefficients,
$\widehat{\operatorname{Newt}}(p) \coloneqq \operatorname{conv}\bigl\{ (\alpha, c_{\alpha}) : \alpha \in \mathcal{A} \bigr\} \subset \RR^{d+1}$.

[Support function]\label{def:support_function}
The \emph{support function} of a nonempty compact convex set $P \subset \RR^{d}$ is
\begin{equation}
	h_{P} \colon \RR^{d} \to \RR,
	\qquad
	h_{P}(x) \coloneqq \max_{u \in P}\, \langle u, x \rangle .
	\label{eq:support_function}
\end{equation}

[Properties of support functions]\label{lem:support_properties}
Let $P, Q \subset \RR^{d}$ be nonempty compact convex sets. Then:
\begin{enumerate}
	\item $h_{P}$ is convex and positively homogeneous, i.e.\ $h_P(\lambda x) = \lambda h_P(x)$ for $\lambda \ge 0$; if $P$ is a polytope with vertex set $\operatorname{vert}(P)$, then $h_{P}(x) = \max_{u \in \operatorname{vert}(P)} \langle u, x \rangle$ is a tropical polynomial with zero coefficients and Newton polytope $P$.
	\item For any nonempty finite set $A \subset \RR^d$ and $x \in \RR^d$, $\max_{u \in \operatorname{conv}(A)} \langle u, x \rangle = \max_{u \in A} \langle u, x \rangle$; in particular $h_{P + Q} = h_{P} + h_{Q}$ and $h_{\operatorname{conv}(P \cup Q)} = \max\{h_{P}, h_{Q}\} = h_P \oplus h_Q$.
	\item $P \subseteq Q$ if and only if $h_{P} \le h_{Q}$ pointwise; in particular $h_{P} = h_{Q}$ implies $P = Q$, so a compact convex set is uniquely determined by its support function.
\end{enumerate}
\hfill\LeanResult{lem:support_properties}

[Newton polytope calculus, cf.\ \parencite{Zhang2018}]\label{prop:newton_calculus}
Let $p$ and $q$ be tropical polynomials on $\RR^d$. Then
\begin{equation}
	\operatorname{Newt}(p \odot q) = \operatorname{Newt}(p) + \operatorname{Newt}(q),
	\qquad
	\operatorname{Newt}(p \oplus q) = \operatorname{conv}\bigl( \operatorname{Newt}(p) \cup \operatorname{Newt}(q) \bigr).
	\label{eq:newton_calculus}
\end{equation}
Moreover, the lifted Newton polytope determines the polynomial function:
\begin{equation}
	p(x) = h_{\widehat{\operatorname{Newt}}(p)}(x, 1)
	\qquad \text{for all } x \in \RR^{d},
	\label{eq:lifted_support}
\end{equation}
and if all coefficients vanish, $c_{\alpha} \equiv 0$, then $p = h_{\operatorname{Newt}(p)}$.
\hfill\LeanResult{prop:newton_calculus}

[The \ac{dc} split is a monotone tropical rational decomposition]\label{thm:split_tropical_rational}
Let $f \colon \RR^d \to \RR$ be a bias-free \ac{relu} \ac{mlp} with scalar output and split streams $g, h \colon \RR^{2d} \to \RR$ defined by \eqref{eq:split_preact_recursion}--\eqref{eq:split_act_recursion}. Then:
\begin{enumerate}
    \item every coordinate of $\act{l}{+}$ and $\act{l}{-}$, and in particular $g$ and $h$, is a positively homogeneous \emph{monotone} tropical polynomial in the doubled variable $(x^+, x^-) \in \RR^{2d}$;
    \item for every splitting $x = x^+ - x^-$,
    \begin{equation}
        f(x) \;=\; g(x^+, x^-) \;-\; h(x^+, x^-),
        \label{eq:tropical_rational_split}
    \end{equation}
    i.e.\ $f$, precomposed with the difference map, is the tropical rational function $g \oslash h$.
\end{enumerate}
\hfill\LeanResult{thm:split_tropical_rational}

[Monotone \ac{cpwl} functions have non-negative gradients]\label{thm:monotone_nonneg_gradients}
Let $u \colon \RR^n \to \RR$ be monotone and \ac{cpwl}. Then every gradient attained by $u$ at a point of differentiability is entrywise non-negative.
\hfill\LeanResult{thm:monotone_nonneg_gradients}

[Subdifferential of a support function]\label{prop:subdifferential_face}
Let $P \subseteq \RR^n$ be a polytope and $x \in \RR^n$. Then $\partial h_P(x) = F_P(x) = \{ p \in P : \langle p, x \rangle = h_P(x) \}$, the maximizing face. In particular, $h_P$ is differentiable at $x$ if and only if $F_P(x)$ is a singleton, in which case $\nabla h_P(x) \in P$.
\hfill\LeanResult{prop:subdifferential_face}

[Imaginative Polytopes live in the non-negative orthant]\label{cor:polytopes_nonneg}
$P_g, P_h \subseteq \RR^{2d}_{\ge 0}$.
\hfill\LeanResult{cor:polytopes_nonneg}

[Vertices encode the attainable split-stream gradients]\label{thm:vertices_gradients}
Let $u \colon \RR^n \to \RR$ be a positively homogeneous convex \ac{cpwl} function with Newton polytope $P = \operatorname{Newt}(u)$. Then
\begin{equation*}
    \operatorname{vert}(P)
    \;=\;
    \bigl\{ \nabla u(\xi) \, : \, \xi \in \RR^n, \ u \text{ differentiable at } \xi \bigr\}.
\end{equation*}
In particular, the attainable gradients of the split streams $g$ and $h$ are exactly the vertex sets $\operatorname{vert}(P_g)$ and $\operatorname{vert}(P_h)$ of the Imaginative Polytopes.
\hfill\LeanResult{thm:vertices_gradients}

[DC--monotone splitting under integrable curvature]\label{thm:smooth_dc_split}
Let $f\colon \RR \to \RR$ be differentiable with locally absolutely continuous derivative $f'$ and $f'' \in L^1(\RR)$. Then the limit $s_- \coloneqq \lim_{u\to-\infty} f'(u)$ exists and $f'$ is bounded. Write $P \coloneqq \max\{f'',0\}$ and $N \coloneqq \max\{-f'',0\}$, so that $f'' = P - N$ with $P, N \ge 0$, and define
\begin{align}
	C_1(x) &\coloneqq f(0) + \int_0^x \Bigl( s_- + \int_{-\infty}^t P(u)\,\diff u \Bigr) \diff t,
	&
	C_2(x) &\coloneqq \int_0^x \int_{-\infty}^t N(u)\,\diff u \,\diff t,
	\label{eq:curvature_antiderivatives}
\end{align}
as well as $M \coloneqq \max\bigl\{ \sup_{x\in\RR} \abs{C_1'(x)},\, \sup_{x\in\RR} \abs{C_2'(x)} \bigr\} < \infty$. Then the functions
\begin{equation}
	g(a,b) \coloneqq C_1(a-b) + M(a+b),
	\qquad
	h(a,b) \coloneqq C_2(a-b) + M(a+b)
	\label{eq:smooth_split_pair}
\end{equation}
are convex on $\RR^2$, non-decreasing in each argument, and satisfy
\begin{equation}
	f(a-b) = g(a,b) - h(a,b) \qquad \text{for all } (a,b) \in \RR^2.
	\label{eq:smooth_splitting_identity}
\end{equation}
\hfill\LeanResult{thm:smooth_dc_split}

[Minimality of the curvature split]\label{prop:curvature_minimality}
Let $f$ be as in Theorem~\ref{thm:smooth_dc_split} and suppose $f = c_1 - c_2$ for convex functions $c_1, c_2 \colon \RR \to \RR$ whose second distributional derivatives are locally integrable functions. Then $c_1'' \ge P$ and $c_2'' \ge N$ almost everywhere. In particular, $(C_1, C_2)$ is, up to a common affine summand, the unique pair of convex functions with $C_1 - C_2 = f$ of pointwise minimal curvature, and among all tilts of the form $(a,b) \mapsto \lambda(a+b)$, $\lambda \ge 0$, the constant $M$ in Theorem~\ref{thm:smooth_dc_split} is the smallest one rendering both components of \eqref{eq:smooth_split_pair} non-decreasing in each argument.
\hfill\LeanResult{prop:curvature_minimality}

[Modern activation functions]\label{cor:modern_activations}
Theorem~\ref{thm:smooth_dc_split} applies to the following activation functions, where $\varphi$ and $\Phi$ denote the standard Gaussian density and distribution function and $\sigma(x) = (1+e^{-x})^{-1}$ the logistic sigmoid:
\begin{enumerate}
	\item \emph{GELU}, $f(x) = x\,\Phi(x)$, with $f''(x) = (2 - x^2)\,\varphi(x)$; the curvature is positive on $(-\sqrt{2}, \sqrt{2})$ and negative outside.
	\item \emph{Swish/SiLU}, $f(x) = x\,\sigma(\beta x)$ with $\beta > 0$, with $f''(x) = \beta\,\sigma'(\beta x)\bigl( 2 + \beta x\,(1 - 2\sigma(\beta x)) \bigr)$; the curvature is positive on a bounded interval around the origin and negative in both tails.
	\item \emph{Mish}, $f(x) = x \tanh\bigl(\log(1 + e^{x})\bigr)$.
	\item \emph{Hyperbolic tangent}, $f(x) = \tanh(x)$, with $f''(x) = -2 \tanh(x)\operatorname{sech}^2(x)$, so $P$ is supported on $(-\infty, 0]$ and $N$ on $[0, \infty)$.
	\item \emph{Logistic sigmoid}, $f = \sigma$, with $f'' = \sigma'\,(1 - 2\sigma)$.
	\item \emph{Softplus at temperature $\theta > 0$}, $f(x) = \theta \log(1 + e^{x/\theta})$, with $f''(x) = \sigma'(x/\theta)/\theta \ge 0$; here $N = 0$, $C_2 = 0$, and the decomposition degenerates to the statement that softplus itself is convex.
\end{enumerate}
In each case $f(0) \ge 0$, so by Remark~\ref{rem:smooth_valid_decomposition} below the resulting pair map preserves non-negativity of the split streams.
\hfill\LeanResult{cor:modern_activations}

[Bounded variation and the piecewise-linear case]\label{rem:bv_extension}
The hypothesis of Theorem~\ref{thm:smooth_dc_split} can be weakened to $f'$ having bounded variation, i.e.\ $f''$ being a finite signed Radon measure $\mu$; replacing $P(u)\,\diff u$ and $N(u)\,\diff u$ in \eqref{eq:curvature_antiderivatives} by the Jordan decomposition $\mu = \mu_+ - \mu_-$ leaves every step of the proof intact. This covers the piecewise-linear activations: for $\relu$ one has $\mu = \delta_0$, hence $C_1(x) = \max\{x, 0\}$, $C_2 = 0$, $s_- = 0$ and $M = 1$, so that
\begin{equation*}
	g(a,b) - h(a,b) = \max\{a - b, 0\} = \max\{a, b\} - b,
\end{equation*}
recovering the splitting identity of Section~\ref{sec:dc_splitting_relu} up to the monotone tilt. Leaky $\relu$ corresponds to $\mu = (1 - \alpha)\,\delta_0$, and ELU to an absolutely continuous curvature $e^{x} \indicator{x < 0}$ plus a possible atom at the origin. Piecewise-linear and smooth activation splittings are thus instances of a single construction.

[Compatibility with valid decompositions]\label{rem:smooth_valid_decomposition}
The pair map $(a,b) \mapsto \bigl(g(a,b), h(a,b)\bigr)$ fits the general decomposition framework of Section~\ref{sec:general_decomposition_def}. Indeed, for $a, b \ge 0$ the Lipschitz bounds $\abs{C_i(x) - C_i(0)} \le M \abs{x}$ and $\abs{a - b} \le a + b$ yield
\begin{equation*}
	g(a,b) \ge f(0) \ge 0,
	\qquad
	h(a,b) \ge 0,
\end{equation*}
for every activation of Corollary~\ref{cor:modern_activations}, so the map sends $\RR^2_{\ge 0}$ to $\RR^2_{\ge 0}$ and is a monotone pairwise activation function; exactness \eqref{eq:smooth_splitting_identity} is precisely the validity condition. For an activation with $f(0) < 0$, shifting both components by $\abs{f(0)}$ restores non-negativity without affecting the difference.

[Decomposition]\label{def:decomposition}
A \emph{decomposition} of a feedforward network~\eqref{eq:original_forward_pass} with $L$ layers is a calculation scheme that propagates non-negative activation pairs $\bigl(\act{l}{+}_i, \act{l}{-}_i\bigr) \in \RR^2_{\ge 0}$ from input to output using only
\begin{enumerate}
	\item \textbf{non-negative linear maps}---matrices with non-negative entries together with non-negative bias vectors---and
	\item \textbf{pairwise activation functions} $\phi \colon \RR^2_{\ge 0} \to \RR^2_{\ge 0}$, $(z^+, z^-) \mapsto (a^+, a^-) = \phi(z^+, z^-)$, applied at every hidden neuron; the final affine readout uses the identity on the pair.
\end{enumerate}
Activations are indexed by $l \in \{0,\dots,L\}$, affine parameters by $l \in \{1,\dots,L\}$. The layer-$0$ pair is any non-negative split of the input,
\begin{equation}
	\bigl(\act{0}{+}_k, \act{0}{-}_k\bigr) \coloneqq \bigl(x_k^+, x_k^-\bigr),
	\qquad
	x_k^+ - x_k^- = x_k,
	\qquad
	x_k^+, x_k^- \ge 0,
	\label{eq:input_split_convention}
\end{equation}
and at each affine layer $l$ a non-negative linear map sends the layer-$(l-1)$ activation pair to the layer-$l$ pre-activation pair $\bigl(\preact{l}{+}_i, \preact{l}{-}_i\bigr) \in \RR^2_{\ge 0}$, to which the pairwise activation is applied for $l<L$. At $l=L$ we set $\act{L}{\pm}=\preact{L}{\pm}$, with no activation or maximum. We call $\bigl(\act{l}{+}_i, \act{l}{-}_i\bigr)$ the \emph{decomposed activation} and $\bigl(\preact{l}{+}_i, \preact{l}{-}_i\bigr)$ the \emph{decomposed pre-activation}.

[Valid decomposition]\label{def:valid_decomposition}
A decomposition (Definition~\ref{def:decomposition}) is \emph{valid} for the network~\eqref{eq:original_forward_pass} with activation function $\varrho$ if the propagated activation pairs satisfy
\begin{equation}
	\act{l}{+}_i - \act{l}{-}_i = \varrho_l\bigl(\preactl{l}_i\bigr) = \actl{l}_i
	\label{eq:validity_condition}
\end{equation}
for every layer $l \in \{0, \dots, L\}$ and every neuron $i$, where at $l = 0$ condition~\eqref{eq:validity_condition} is read as $\act{0}{+}_k - \act{0}{-}_k = x_k$.

[Validity recovers the network]\label{prop:validity_recovery}
Let a decomposition use the canonical non-negative linear map \eqref{eq:split_pos}--\eqref{eq:split_neg}. If the validity condition~\eqref{eq:validity_condition} holds at layer $l-1$, then the decomposed pre-activations at layer $l$ satisfy
\begin{equation}
	\preact{l}{+}_i - \preact{l}{-}_i = \preactl{l}_i
	\qquad \text{for every neuron } i.
	\label{eq:preactivation_difference}
\end{equation}
Consequently, every valid decomposition recovers the original network output as the difference of the final decomposed activations,
\begin{equation}
	f(x) = \act{L}{+} - \act{L}{-}.
	\label{eq:output_recovery}
\end{equation}
\hfill\LeanResult{prop:validity_recovery}

[Mixing decomposition function]\label{def:fmix}
For $\eta \in [0,1]$, the \emph{mixing decomposition function} is
\begin{equation}
	\fmix(z^+, z^-) \coloneqq \bigl(\, \eta \max\{z^+, z^-\} + (1-\eta)\, z^+, \;\; \eta\, z^- + (1-\eta) \min\{z^+, z^-\} \,\bigr).
	\label{eq:fmix_def}
\end{equation}
The decomposition obtained by applying $\fmix$ at every hidden neuron and retaining the identity pair at the affine output on top of the canonical non-negative linear map \eqref{eq:split_pos}--\eqref{eq:split_neg}, with the input convention~\eqref{eq:input_split_convention}, is called the \emph{Mixing Decomposition}; when comparing decompositions we tag its activations as $a_{\mathrm{mix}}^{(l,\pm,\eta)}$.

[Layerwise recovery of the Mixing Decomposition]\label{thm:mixing_recovery}
Let the activation pairs be propagated by the canonical non-negative linear map \eqref{eq:split_pos}--\eqref{eq:split_neg}, initialised by~\eqref{eq:input_split_convention}, and updated by $\fmix$ for some $\eta \in [0,1]$. Then for every layer $l$ and neuron $i$,
\begin{equation}
	a_{\mathrm{mix},i}^{(l,+,\eta)} - a_{\mathrm{mix},i}^{(l,-,\eta)} = \varrho_l\bigl(\preactl{l}_i\bigr) = \actl{l}_i,
	\label{eq:mixing_recovery}
\end{equation}
i.e.\ the Mixing Decomposition is a valid decomposition (Definition~\ref{def:valid_decomposition}) of the \ac{relu} network for every $\eta \in [0,1]$.
\hfill\LeanResult{thm:mixing_recovery}

[$\eta = 1$ convex characterisation of the Mixing Decomposition]\label{thm:mixing_convex_extreme}
Under the input convention~\eqref{eq:input_split_convention} with split components $x_k^\pm$ that are convex functions of $x$ (e.g.\ the entrywise split $x^\pm = \posneg{x}{\pm}$, or any affine split), the $\eta = 1$ mixing decomposed activations
\begin{equation*}
	a_{\mathrm{mix},i}^{(l,+,1)}(x) = \max\bigl\{ \preact{l}{+}_i(x),\, \preact{l}{-}_i(x) \bigr\}
	\qquad \text{and} \qquad
	a_{\mathrm{mix},i}^{(l,-,1)}(x) = \preact{l}{-}_i(x)
\end{equation*}
are convex in $x$ at every hidden layer $l$ and neuron $i$; at the final layer, both streams are nonnegative affine combinations of the previous streams and remain convex. Consequently $\actl{l}_i = a_{\mathrm{mix},i}^{(l,+,1)} - a_{\mathrm{mix},i}^{(l,-,1)}$ is a difference of convex functions, the standard \ac{dc} representation of the \ac{cpwl} function computed by the network \parencite{Arora2018,hiddenMono}.
\hfill\LeanResult{thm:mixing_convex_extreme}

[DC split as the $\eta = 1$ mixing endpoint]\label{cor:dc_split_endpoint}
Set $\eta = 1$ in Definition~\ref{def:fmix} and drop the decomposition tag, writing $\act{l}{\pm} \coloneqq a_{\mathrm{mix}}^{(l,\pm,1)}$. The resulting \emph{\ac{dc} split} propagates, for hidden layers $l = 1, \dots, L-1$,
\begin{equation}
	\act{l}{+} = \max\bigl\{ \preact{l}{+},\, \preact{l}{-} \bigr\},
	\qquad
	\act{l}{-} = \preact{l}{-}
	\label{eq:dc_split_activations}
\end{equation}
entrywise, and sets $\act{L}{\pm}=\preact{L}{\pm}$ at the final affine readout, with the decomposed pre-activations \eqref{eq:split_pos}--\eqref{eq:split_neg} induced by the weight split $\Wl{l} = \Wsig{l}{+} - \Wsig{l}{-}$ and the input split $x = x^+ - x^-$. It is a valid decomposition of the \ac{relu} network, and under the input convention of Theorem~\ref{thm:mixing_convex_extreme} its decomposed activations are convex functions of the input.
\hfill\LeanResult{cor:dc_split_endpoint}

[Monotonicity and convexity of the split streams]\label{prop:stream_properties}
For every $0 \le l \le L$, the stream functions $g^{(l)}$ and $h^{(l)}$ of~\eqref{eq:stream_functions} are convex and non-decreasing in each coordinate of the pair $(x^+, x^-) \in \RR^{d^{(l)}} \times \RR^{d^{(l)}}$.
\hfill\LeanResult{prop:stream_properties}

[Correctness of the split forward pass]\label{thm:split_correct}
For every $0 \le l \le L$ and all $x^+, x^- \in \RR^{d^{(l)}}_{\ge 0}$,
\begin{equation}
	f^{(l)}\bigl( x^+ - x^- \bigr)
	= \bigl( g^{(l)} - h^{(l)} \bigr)(x^+, x^-).
	\label{eq:split_correctness}
\end{equation}
\hfill\LeanResult{thm:split_correct}

[Stopping decomposition function]\label{def:fstop}
The \emph{stopping decomposition function} is
\begin{equation}
	\fstop(z^+, z^-) \coloneqq \bigl(\, \1\bigl[z^+ - z^- > 0\bigr]\, z^+, \;\; \1\bigl[z^+ - z^- > 0\bigr]\, z^- \,\bigr).
	\label{eq:fstop_def}
\end{equation}
The decomposition obtained by applying $\fstop$ at every hidden neuron and retaining the identity pair at the affine output on top of the canonical non-negative linear map \eqref{eq:split_pos}--\eqref{eq:split_neg}, with the input convention~\eqref{eq:input_split_convention}, is called the \emph{Stopping Decomposition}; when comparing decompositions we tag its activations as $a_{\mathrm{stop}}^{(l,\pm)}$.

[Validity of the Stopping Decomposition]\label{thm:stopping_validity}
Let the activation pairs be propagated by the canonical non-negative linear map \eqref{eq:split_pos}--\eqref{eq:split_neg}, initialised by~\eqref{eq:input_split_convention}, and updated by $\fstop$. Then for every layer $l$ and neuron $i$,
\begin{equation}
	a_{\mathrm{stop},i}^{(l,+)} - a_{\mathrm{stop},i}^{(l,-)} = \varrho_l\bigl(\preactl{l}_i\bigr) = \actl{l}_i,
	\label{eq:stopping_recovery}
\end{equation}
i.e.\ the Stopping Decomposition is a valid decomposition (Definition~\ref{def:valid_decomposition}) of the \ac{relu} network.
\hfill\LeanResult{thm:stopping_validity}

[Monotonicity of the Stopping Decomposition on linear regions]\label{lem:stop_monotone}
On each linear region of the \ac{relu} network---a maximal subset of input space on which all gate indicators $\1\bigl[\preactl{l}_j > 0\bigr]$ are constant---each stopping decomposed activation $a_{\mathrm{stop},i}^{(l,\pm)}$ is a non-negative-linear (i.e.\ affine with non-negative coefficients) function of the input pair $(x^+, x^-) \in \RR^{2 d^{(0)}}_{\ge 0}$, hence monotone non-decreasing in each coordinate $x_k^+$ and $x_k^-$.
\hfill\LeanResult{lem:stop_monotone}

[Parity path view on the Stopping Decomposition]\label{lem:parity_path}
Fix a \ac{relu} network with weights $\Wl{l}$ and, for clarity, vanishing biases. For a neuron $i$ in layer $l \ge 1$, a \emph{backward path} to the input is a list $P = (P_l, \dots, P_0)$ with $P_l = i$ and $P_t$ a neuron in layer $t$, using weights $\Wl{t}_{P_t, P_{t-1}}$. Define the absolute weight product, parity sign, and gate factor
\begin{equation*}
	\abs{w}(P) \coloneqq \prod_{t=1}^{l} \bigl|\Wl{t}_{P_t, P_{t-1}}\bigr|,
	\qquad
	\operatorname{sgn}(P) = + \iff \#\bigl\{ t : \Wl{t}_{P_t, P_{t-1}} < 0 \bigr\} \text{ is even},
	\qquad
	G_{<l}(P) \coloneqq \prod_{t=1}^{l-1} \1\bigl[\preactl{t}_{P_t} > 0\bigr].
\end{equation*}
Then the decomposed pre-activations of the Stopping Decomposition admit the path-sum representation
\begin{equation}
	\preact{l}{+}_i = \sum_{P :\, P_l = i} G_{<l}(P)\, \abs{w}(P)\, x_{P_0}^{\operatorname{sgn}(P)},
	\qquad
	\preact{l}{-}_i = \sum_{P :\, P_l = i} G_{<l}(P)\, \abs{w}(P)\, x_{P_0}^{\operatorname{sgn}(P)'},
	\label{eq:parity_path_sums}
\end{equation}
where $\operatorname{sgn}(P)' $ denotes the opposite sign of $\operatorname{sgn}(P)$.
\hfill\LeanResult{lem:parity_path}

[Regularized decomposition function]\label{def:freg}
Let $\Omega \colon [0,1] \to \RR_{\le 0}$ be a proper, closed, convex regularizer with $\Omega \le 0$. Define the \emph{regularized gate} and the \emph{conjugate activation}
\begin{equation}
	\pi_\Omega(\Delta) \in \argmax_{\pi \in [0,1]} \bigl\{ \pi \Delta - \Omega(\pi) \bigr\},
	\qquad
	\Omega^*(\Delta) \coloneqq \max_{\pi \in [0,1]} \bigl\{ \pi \Delta - \Omega(\pi) \bigr\},
	\label{eq:regularized_gate}
\end{equation}
where an arbitrary maximizer is fixed if several exist. The \emph{regularized decomposition function} is
\begin{equation}
	\freg(z^+, z^-) \coloneqq \Bigl(\, \pi_\Omega(\Delta)\, z^+ - \Omega\bigl(\pi_\Omega(\Delta)\bigr), \;\; \pi_\Omega(\Delta)\, z^- \,\Bigr),
	\qquad
	\Delta \coloneqq z^+ - z^-.
	\label{eq:freg_def}
\end{equation}

[Validity of regularized decompositions]\label{thm:freg_validity}
Let $\Omega$ be as in Definition~\ref{def:freg}, and let the activation pairs be propagated by the canonical non-negative linear map \eqref{eq:split_pos}--\eqref{eq:split_neg}, initialised by~\eqref{eq:input_split_convention}, and updated by $\freg$ at hidden layers, with the identity pair at the final affine readout. Then for every hidden layer $l$ and neuron $i$,
\begin{equation}
	\act{l}{+}_i - \act{l}{-}_i = \Omega^*\bigl(\preactl{l}_i\bigr),
	\label{eq:freg_recovery}
\end{equation}
At the final affine layer, the difference is $\preactl{L}=\actl{L}$. Thus $\freg$ is a valid decomposition of the network~\eqref{eq:original_forward_pass} with activation function $\varrho = \Omega^*$. Moreover, $\Omega^*$ is convex, non-decreasing, and $1$-Lipschitz, and wherever $\Omega^*$ is differentiable the gate is its derivative, $\pi_\Omega(\Delta) = (\Omega^*)'(\Delta) \in [0,1]$.
\hfill\LeanResult{thm:freg_validity}

[Softplus Decomposition]\label{cor:fsoft}
For $\Omega = \Omega_\theta$ as in~\eqref{eq:entropy_regularizer}, the regularized gate and conjugate activation are
\begin{equation}
	\pi_{\Omega_\theta}(\Delta) = \sigma'_\theta(\Delta) \coloneqq \frac{1}{1 + e^{-\Delta/\theta}},
	\qquad
	\Omega_\theta^*(\Delta) = \sigma_\theta(\Delta) \coloneqq \theta \log\bigl( 1 + e^{\Delta/\theta} \bigr),
	\label{eq:sigmoid_gate}
\end{equation}
the sigmoid gate and the softplus function at temperature $\theta$. The resulting decomposition function is the \emph{softplus decomposition function}
\begin{equation}
	\fsoft(z^+, z^-) = \Bigl(\, \sigma'_\theta(\Delta)\, z^+ + \theta\, H\bigl(\sigma'_\theta(\Delta)\bigr), \;\; \sigma'_\theta(\Delta)\, z^- \,\Bigr),
	\qquad
	\Delta = z^+ - z^-,
	\label{eq:fsoft_def}
\end{equation}
and by Theorem~\ref{thm:freg_validity} it yields a valid decomposition---the \emph{Softplus Decomposition}---of the softplus network with parameter $\beta = 1/\theta$. In the limit $\theta \to 0$, $\fsoft \to \fstop$ pointwise on $\{\Delta \neq 0\}$.
\hfill\LeanResult{cor:fsoft}

[Probit regularizer and GELU]\label{rem:probit_gelu}
The framework is not tied to the entropy. For the probit regularizer $\Omega_\Phi(\pi) \coloneqq -\phi\bigl(\Phi^{-1}(\pi)\bigr)$, with $\phi, \Phi$ the standard Gaussian density and distribution function, one has $\frac{\diff}{\diff \pi}\bigl(-\Omega_\Phi\bigr)(\pi) = -\Phi^{-1}(\pi)$, so the first-order condition for~\eqref{eq:regularized_gate} gives the gate $\pi_{\Omega_\Phi}(\Delta) = \Phi(\Delta)$ and the conjugate activation
\begin{equation*}
	\Omega_\Phi^*(\Delta) = \Delta\, \Phi(\Delta) + \phi(\Delta) = \E_{\varepsilon \sim \mathcal{N}(0,1)}\bigl[ \max(\Delta + \varepsilon, 0) \bigr],
\end{equation*}
the Gaussian smoothing of the \ac{relu}. Up to $\phi(\Delta)$, which common implementations drop, this is GELU \parencite{Hendrycks2016}, and the gate $\Phi(\Delta) = \E_\varepsilon\bigl[\1[\Delta + \varepsilon > 0]\bigr]$ is the hard stopping gate averaged over a Gaussian shift of its threshold---matching the original stochastic-gate motivation for GELU. The distinction matters for exact decomposability: the conjugate activation $\Omega_\Phi^*(\Delta) = \Delta\,\Phi(\Delta) + \phi(\Delta)$ is the object recovered by $\freg$ and, being a Fenchel conjugate, is convex, non-decreasing, and $1$-Lipschitz (Theorem~\ref{thm:freg_validity}). The \emph{implemented} GELU $\Delta \mapsto \Delta\,\Phi(\Delta)$ that drops $\phi(\Delta)$ is non-monotone---it dips below zero for $\Delta < 0$---and is therefore \emph{not} itself a conjugate activation $\Omega^*$; the exactly decomposable object is the $+\phi(\Delta)$ variant, and networks using the dropped-term GELU are only approximately captured by this decomposition.

[Shift equivariance of the split streams]\label{thm:shift_forward}
For any $0 \le l \le L$ and any $c, a^{(+)}, a^{(-)} \in \RR^{d^{(l)}}$ with $a^{(\pm)}, a^{(\pm)} + c \ge 0$,
\begin{equation}
	g^{(l)}\bigl( a^{(+)} + c,\, a^{(-)} + c \bigr) = g^{(l)}\bigl( a^{(+)},\, a^{(-)} \bigr) + W_{\mathrm{abs}}^{[l, \rightarrow]}\, c,
	\qquad
	h^{(l)}\bigl( a^{(+)} + c,\, a^{(-)} + c \bigr) = h^{(l)}\bigl( a^{(+)},\, a^{(-)} \bigr) + W_{\mathrm{abs}}^{[l, \rightarrow]}\, c.
	\label{eq:shift_forward}
\end{equation}
In particular, $\bigl(g^{(l)} - h^{(l)}\bigr)\bigl( a^{(+)} + c,\, a^{(-)} + c \bigr) = \bigl(g^{(l)} - h^{(l)}\bigr)\bigl( a^{(+)},\, a^{(-)} \bigr)$.
\hfill\LeanResult{thm:shift_forward}

[Sensitivity complementarity]\label{thm:delta_connection}
For every $0 \le l \le L$,
\begin{equation}
	\delta^{(l,+,g)} = W_{\mathrm{abs}}^{[l, \rightarrow]} - \delta^{(l,-,g)},
	\qquad
	\delta^{(l,+,h)} = W_{\mathrm{abs}}^{[l, \rightarrow]} - \delta^{(l,-,h)}.
	\label{eq:delta_complementarity}
\end{equation}
\hfill\LeanResult{thm:delta_connection}

[Closed formulas for the stabilized split gradients]\label{thm:closed_formula_shift}
With $\overline{\alpha}_j \coloneqq \prod_{j \le i \le L} \bigl( 1 - 2 \alpha^{(i)} \bigr)$, the stabilized backward pass \eqref{eq:delta_int_pos}--\eqref{eq:delta_shift_def} computes, for every $0 \le l \le L$,
\begin{align}
	\delta_{\mathrm{shift}}^{(l,g)}
	&= \frac{1}{2} \Bigl[ \delta^{(l)} - \sum_{l \le j < L} \overline{\alpha}_{j+1}\; W_{\mathrm{abs}}^{[j+1, \rightarrow]} \bigl( M^{(j+1,-)} \Wl{j+1} \bigr) \prod_{i = (j-1), \dots, l} W^{(i+1,x)} \Bigr],
	\label{eq:closed_formula_g}\\
	\delta_{\mathrm{shift}}^{(l,h)}
	&= -\frac{1}{2} \Bigl[ \delta^{(l)} + \sum_{l \le j < L} \overline{\alpha}_{j+1}\; W_{\mathrm{abs}}^{[j+1, \rightarrow]} \bigl( M^{(j+1,-)} \Wl{j+1} \bigr) \prod_{i = (j-1), \dots, l} W^{(i+1,x)} \Bigr].
	\label{eq:closed_formula_h}
\end{align}
The $j=L-1$ correction term is zero because $M^{(L,-)}=0$: no minimum or auxiliary $Q$ source is inserted at the affine readout. In particular, $\delta_{\mathrm{shift}}^{(l,g)} - \delta_{\mathrm{shift}}^{(l,h)} = \delta^{(l)}$ for all $l$; for $\alpha^{(i)} \equiv 0$ (i.e.\ $\overline{\alpha}_j = 1$) the formulas describe the plain split-pair gradients, and for $\alpha^{(i)} \equiv 1/2$ all correction terms vanish and the stabilized quantities are $\pm\delta^{(l)}/2$, halves of the original gradient.
\hfill\LeanResult{thm:closed_formula_shift}

[Correctness of split convolution]\label{prop:conv_correct}
The chunk~\eqref{eq:conv_split} maps non-negative pairs to non-negative pairs, each output component is a non-negative linear (affine) function of $(u^+, u^-)$---hence convex and non-decreasing in each coordinate---and
\begin{equation*}
	v^+ - v^- = K * (u^+ - u^-) + b.
\end{equation*}
\hfill\LeanResult{prop:conv_correct}

[Non-negative linear chunks preserve the invariants]\label{lem:linear_chunk}
Let a chunk compute an affine map $u \mapsto A u + c$ with real matrix $A = \posneg{A}{+} - \posneg{A}{-}$ and bias $c = \posneg{c}{+} - \posneg{c}{-}$, split streamwise as
\begin{equation*}
	v^+ \coloneqq \posneg{A}{+} u^+ + \posneg{A}{-} u^- + \posneg{c}{+},
	\qquad
	v^- \coloneqq \posneg{A}{-} u^+ + \posneg{A}{+} u^- + \posneg{c}{-}.
\end{equation*}
Then the chunk maps non-negative pairs to non-negative pairs, each component is affine with non-negative coefficients in $(u^+, u^-)$---hence convex and non-decreasing in each coordinate---and $v^+ - v^- = A(u^+ - u^-) + c$.
\hfill\LeanResult{lem:linear_chunk}

[Correctness of gated max-pooling]\label{prop:maxpool_correct}
For a pooling window $[q]$, define the split chunk
\begin{equation}
	v^+ \coloneqq \max_{j \in [q]} \Bigl\{ u_j^+ + \sum_{i \in [q],\, i \neq j} u_i^- \Bigr\},
	\qquad
	v^- \coloneqq \sum_{i \in [q]} u_i^-.
	\label{eq:maxpool_split}
\end{equation}
Then $v^\pm \ge 0$ for $u^\pm \ge 0$, both components are convex and non-decreasing in each coordinate of $(u^+, u^-)$, and
\begin{equation}
	v^+ - v^- = \max_{j \in [q]} \bigl( u_j^+ - u_j^- \bigr).
	\label{eq:maxpool_identity}
\end{equation}
\hfill\LeanResult{prop:maxpool_correct}

[Correctness of the CNN split pass]\label{thm:cnn_split_correct}
Let $\mathcal{G}$ be a feedforward computation graph composed of the chunk types above, computing the function $x \mapsto f(x)$. Then for every input split $x = x^+ - x^-$ with $x^\pm \ge 0$, the split pass produces non-negative pairs satisfying the difference invariant
\begin{equation*}
	v_m^+ - v_m^- = v_m \qquad \text{for every chunk } C_m,
\end{equation*}
where $v_m$ is the corresponding original activation; in particular $f(x) = v_M^+ - v_M^-$. If neither winner-takes-all pooling nor input-dependent re-centering is used, every $v_m^\pm$ is convex in $(x^+, x^-)$ and non-decreasing in each coordinate.
\hfill\LeanResult{thm:cnn_split_correct}

[Gradient representation]\label{ptnb:thm:gradient}
The Stopping Game allows a subgame-perfect Nash equilibrium, unique up to tie-breaking at
zero-activation neurons.
On strict gate cells (and with unique max-pooling winners where applicable), under the stop-at-tie-breaks equilibrium the discounted occupation measure $\Gamma_x(s_{i,p}^{(l)})
    \ge 0$ equals the output derivative with respect to the corresponding \emph{Stopping Decomposition}
activation. At ties, the corresponding identities refer to the backward quantities selected by the stated gate and winner conventions.
On these cells, the gradient of $f$ with respect to the input is the difference $\Gamma_x(s_{i,+}^{(0)}) -
    \Gamma_x(s_{i,-}^{(0)})$.
\hfill\LeanResult{ptnb:thm:gradient}

[$\alpha\beta$-\ac{lrp} representation]\label{ptnb:thm:lrp-recovery}\label{thm:lrp_recovery}
For $\tau>0$, the Gibbs policies of Eq.~\eqref{ptnb:eq:gibbs-policy} and stopping decisions from the corresponding continuation values yield a canonical SPNE of the entropy-regularized \ac{rg}. We select stopping at every activation log tie and absorption for an empty routing stream, as specified in Remark~\ref{ptnb:rem:routing-spne-uniqueness}. At the anchor $\tau=1$, the selected gate is $\mathbf{1}[z>0]$ and the
$\alpha\beta$-\ac{lrp} attribution map in~\eqref{ptnb:eq:lrp-ab} equals $R_i^{(l)} =
    f(x)\,\bigl(\Gamma_x(s_{i,+}^{(l)}) - \Gamma_x(s_{i,-}^{(l)})\bigr)$.
\hfill\LeanResult{ptnb:thm:lrp-recovery}

[Layerwise Recovery of the Original Activations]\label{ptnb:thm:decomp-recovery}
For every layer $l$ and neuron $j$,
\begin{align}\label{ptnb:eq:decomp-recovery-stop-mix}
    a_{\mathrm{stop},j}^{(l,+)} - a_{\mathrm{stop},j}^{(l,-)}
    =
    a_j^{(l)} = \relu\!\bigl(z_j^{(l)}\bigr).
\end{align}
\hfill\LeanResult{ptnb:thm:decomp-recovery}

[Path view on the Stopping Decomposition]\label{ptnb:lem:parity-path}
Fix a feedforward ReLU network with weights $W^{(l)}$ (biases ignored; see remark at end of proof).
For neuron $j$ in layer $l \ge 1$, call a \emph{backward path} from $j$ to the input layer a list
of neuron indices
\begin{align}
    P = (P_l, P_{l-1}, \dots, P_0), \qquad P_l = j,
\end{align}
with $P_t$ indexing a neuron in layer $t$. The edges of $P$ use the weights $W^{(t)}_{P_{t-1},
    P_t}$ for $t = 1, \dots, l$. Define
\begin{align}
    w(P) \coloneqq \prod_{t=1}^{l} W^{(t)}_{P_{t-1}, P_t},
    \qquad
    |w|(P) \coloneqq \prod_{t=1}^{l} \bigl| W^{(t)}_{P_{t-1}, P_t} \bigr|,
\end{align}
the parity sign
\begin{align}
    \mathrm{sgn}(P) \in \{+,-\},
    \qquad
    \mathrm{sgn}(P) = + \iff \#\bigl\{t : W^{(t)}_{P_{t-1}, P_t} < 0\bigr\} \text{ is even,}
\end{align}
and the \emph{gate factor} (1 iff every gate on $P$ at intermediate layers $1,\dots,l-1$ is open)
\begin{align}
    G_{<l}(P) \coloneqq \prod_{t=1}^{l-1} \1\!\bigl[z_{P_t}^{(t)} > 0\bigr].
\end{align}
Then the decomposed pre-activations~\eqref{ptnb:eq:split-pos}--\eqref{ptnb:eq:split-neg} admit the path-sum
representation
\begin{align}
    z_j^{(l,+)} &= \sum_{P:\, P_l = j} G_{<l}(P)\, |w|(P)\, x_{P_0}^{\mathrm{sgn}(P)},
    \label{ptnb:eq:parity-plus}\\
    z_j^{(l,-)} &= \sum_{P:\, P_l = j} G_{<l}(P)\, |w|(P)\, x_{P_0}^{\mathrm{sgn}(P)'}.
    \label{ptnb:eq:parity-minus}
\end{align}
\hfill\LeanResult{ptnb:lem:parity-path}

[Forward Equivalence for Stopping Game]\label{ptnb:thm:forward-stopping}
The game admits a Subgame Perfect Nash Equilibrium (SPNE) where both players follow the same pure
strategy:
\begin{align} \label{ptnb:eq:adf-spne-policy}
    \pi_q^{\star}\bigl(s_{j,q}^{(l, \mathrm{act})}\bigr) = \1\bigl[z_j^{(l)} > 0\bigr].
\end{align}
Under this equilibrium, the player-specific game values and the game values satisfy
\begin{align}\label{ptnb:eq:adf-spne-values}
    \tilde{V}_p^{\pi^\star}\bigl(s_{j,q}^{(l, \mathrm{act})}\bigr) = a_{\mathrm{stop},j}^{(l, p \oplus
    q)},
    \qquad
    V_p^{\pi^\star}\bigl(s_{j,q}^{(l, \mathrm{act})}\bigr) = \xi_{p,q}\, a_j^{(l)}.
\end{align}
\hfill\LeanResult{ptnb:thm:forward-stopping}

[Forward Equivalence for Addition]\label{ptnb:prop:addition-equivalence}
The player-specific state value at the addition state equals the sum of the operand state values,
\begin{align}
    \tilde V_p^{\pi}\bigl(s_{z,q}^{\mathrm{add}}\bigr)
    \;=\;
    \tilde V_p^{\pi}(s_{x,q}) + \tilde V_p^{\pi}(s_{y,q}).
\end{align}
Consequently, if the operand states recover the Stopping-Decomposition activations---$\tilde
    V_p^{\pi^\star}(s_{x,q}) = x^{(p\oplus q)}$ and $\tilde V_p^{\pi^\star}(s_{y,q}) = y^{(p\oplus
    q)}$---then $\tilde V_p^{\pi^\star}(s_{z,q}^{\mathrm{add}}) = z^{(p\oplus q)}$, preserving the
forward equivalence of Theorem~\ref{ptnb:thm:forward-stopping} across the residual sum.

[Max-Pooling Decision State]\label{ptnb:def:maxpool-subgame}
For a pooled scalar output $z = \max\{x_1, \dots, x_m\}$, the \emph{pooling state} $s_{z,q}^{\max}$
has active player $q \in \{+, -\}$ and admissible action set $\mathcal{A}(s_{z,q}^{\max}) = \{1,
    \dots, m\}$ indexing the operand states $s_{x_1,q}, \dots, s_{x_m,q}$. Under action $k$, the
transition is deterministic,
\begin{align}
    \P\bigl(s_{x_k,q} \,\big|\, s_{z,q}^{\max}, k\bigr) \coloneqq 1,
\end{align}
with player $q$ retained at the chosen operand. The immediate payoff is $r_p(s_{z,q}^{\max}, k)
    \coloneqq 0$ for both $p \in \{+,-\}$, and the structural discount is $\gamma_{\mathrm{O}}
    \coloneqq 1$.

[Forward Equivalence for Max Pooling]\label{ptnb:prop:maxpool-equivalence}
Assume the operand states recover the Stopping-Decomposition activations, $\tilde
    V_p^{\pi^\star}(s_{x_k,q}) = x_k^{(p\oplus q)}$ for all $k$, with non-negative operand activations
$x_k \ge 0$. Then at the SPNE of the subgame rooted at $s_{z,q}^{\max}$,
\begin{align}
    \tilde V_p^{\pi^\star}\bigl(s_{z,q}^{\max}\bigr) \;=\; z^{(p\oplus q)},
\end{align}
so the pooling state inherits the same Stopping-Decomposition identity as its winning operand and
the forward equivalence of Theorem~\ref{ptnb:thm:forward-stopping} extends across the pooling node.

[Activation--Occupation Correspondence]\label{ptnb:thm:deriv-occ}\label{thm:gradient_occupation}
Fix a neuron state $s = s_{j,q}^{(m, \mathrm{act})}$ and a layer $l \le m$ (for $l = 0$,
$s_{i,\cdot}^{(0,\mathrm{act})}$ denotes the terminal state $s_{i,\cdot}^{(0)}$). Under the
stop-at-tie-breaks equilibrium fixed by the boundary conventions of
Section~\ref{ptnb:app:notation-identities} (uniquely fixing the SPNE at ReLU gates with $z = 0$ and at
max-pooling states with multiple maximizers), the discounted occupation measures exactly represent,
in a multi-trajectory ReLU network (e.g., a ResNet or a CNN with max pooling), the local
Stopping-Decomposition and scalar activation derivatives on open cells with nonzero ReLU preactivations and unique max-pooling winners. At ties, the same formulas represent the backward quantities computed using the selected gates and winners; they do not assert classical differentiability of the individual stopping streams, which can be discontinuous there:
\begin{enumerate}
    \item \textbf{Stopping-Decomposition Gradient:}
        \begin{align}
            \frac{\partial a_{\mathrm{stop},j}^{(m, p \oplus q)}}{\partial a_{\mathrm{stop},i}^{(l, k)}}
            \;=\;
            \Gamma_x\!\bigl(s_{i, p \oplus k}^{(l, \mathrm{act})} \bigm| s\bigr).
        \end{align}
    \item \textbf{Network Activation Gradient.} The ordinary-network gradient of $a_j^{(m)}$ with respect to
        the scalar activation $a_i^{(l)}$ is
        \begin{align}
            \frac{\partial a_j^{(m)}}{\partial a_i^{(l)}}
            \;=\;
            \xi_{q, +}\bigl(\Gamma_x(s_{i, +}^{(l, \mathrm{act})} \mid s) - \Gamma_x(s_{i, -}^{(l,
            \mathrm{act})} \mid s)\bigr).
        \end{align}
\end{enumerate}
\hfill\LeanResult{ptnb:thm:deriv-occ}

[SPNE and Forward Equivalence of the Routing Game]\label{ptnb:thm:routing-forward}
\leavevmode
\begin{description}
    \item[\textnormal{(i) \emph{SPNE existence for every $\tau > 0$ and $\varepsilon \ge 0$.}}]
        For every $\tau > 0$ and every $\varepsilon \ge 0$, the entropy-regularized two-player Routing Game
        of Definition~\ref{ptnb:def:routing-recursion} (with linear-state entropy weight $\tau\,\mathcal{H}$ and
        outside-option stabilizer $\varepsilon$) admits a subgame-perfect Nash equilibrium
        (see~\eqref{ptnb:eq:routing-spne-linear}--\eqref{ptnb:eq:routing-spne-stop} in the proof for the explicit
        form of the equilibrium policy). We write $\cdot^\star$ for equilibrium quantities throughout.

    \item[\textnormal{(ii) \emph{Forward equivalence at the anchor $\tau=1$, $\varepsilon\geq 0$.}}]
        At $\tau=1$ and $\varepsilon \geq 0$, the equilibrium quantities recover the network forward pass:
        for every layer $l$, neuron $j$, player labels $p,q,r$, and stream sign $\kappa\in\{+,-\}$,
        \begin{align}
            V_r\bigl(s_{j,q,\kappa}^{(l, lin)}\bigr) &= \ell\bigl(\delta_{r,q} \, (\Sigma_j^{(l,\kappa)} +
            \varepsilon)\bigr), \label{ptnb:eq:routing-forward-linear}\\
            Q_r\left( s_{j,p}^{(l, act)}, \text{continue} \right) &= \ell \left( \xi_{r,p} \cdot z^{(l)}_j
            \right), \label{ptnb:eq:routing-forward-continue} \\
            V_r\bigl(s_{j,p}^{(l, act)}\bigr) &= \ell\bigl( \delta_{r,p}\ \cdot a_j^{(l)} \bigr),
            \label{ptnb:eq:routing-forward-act}\\
            \pi_p^\star\bigl(s_{j,p}^{(l, act)}\bigr) &= \1[z_j^{(l)} > 0]. \label{ptnb:eq:routing-forward-stop}
        \end{align}
\end{description}
\hfill\LeanResult{ptnb:thm:routing-forward}

[Recovery of Multi-Path $\alpha\beta$-\ac{lrp}]\label{ptnb:thm:ab-recovery}
For every $\varepsilon \ge 0$ and every input with $f(x)=a_u^{(L)}>0$ (if $f(x)=0$ the root player
stops and $R^{(l)}=f(x)\Gamma^{(l)}=0$ trivially), under the stop-at-tie-breaks equilibrium
(Remark~\ref{ptnb:rem:routing-spne-uniqueness}; ties at max-pooling states broken by the smallest index)
at the anchor temperature $\tau = 1$ and stabilizer $\varepsilon$, with the cumulative trajectory
discount~\eqref{ptnb:eq:routing-discount} and the occupation measure $\Gamma_j^{(l)}$
from~\eqref{ptnb:eq:routing-Gamma-pair}:
\begin{enumerate}
    \item \textbf{Linear Map.} The per-neuron difference $\Gamma^{(l)}_j$ of~\eqref{ptnb:eq:routing-Gamma-pair}
        satisfies
        \begin{align}\label{ptnb:eq:lrp-eps-recovery}
            \Gamma^{(l-1)}_i
            \;=\; \sum_j \left(
            \alpha \frac{[a_i^{(l-1)} W_{ij}^{(l)}]^+}{\varepsilon + \Sigma_j^{(l,+)}}
            -
            \beta \frac{[a_i^{(l-1)} W_{ij}^{(l)}]^-}{\varepsilon + \Sigma_j^{(l,-)}}
            \right) \Gamma^{(l)}_j.
        \end{align}
        Because~\eqref{ptnb:eq:lrp-eps-recovery} and~\eqref{ptnb:eq:lrp-eps-recursion} share their computational
        step, $\Gamma^{(l)}_j \cdot R_u^{(L)} = R^{(l)}_j$ at every layer; in particular $R^{(l)}_j =
            f(x)\,\Gamma^{(l)}_j$ for the seed $R^{(L)}_u = f(x)$. The same formula covers the fused input
        layer with $a^{(0)} = x$. At $\varepsilon = 0$ this reduces to the unstabilized
        $\alpha\beta$-\ac{lrp} redistribution (not conservative: bias nodes absorb relevance); at
        $\varepsilon > 0$ \ch{it is the $\alpha\beta$ rule with the stabilization convention adopted here,
        i.e.\ \eqref{ptnb:eq:lrp-ab} with $\varepsilon$ added to each sign denominator separately.}
    \item \textbf{Residual Addition.} Let $z = x_{\mathrm{op}} + y_{\mathrm{op}}$ be an addition node with
        addition state $s^{\mathrm{add}}_{z,p}$ and operand states $s_{x_{\mathrm{op}},p},
            s_{y_{\mathrm{op}},p}$ as in Section~\ref{ptnb:app:routing-skip}. For every player label $p\in\{+,-\}$,
        with the edge occupation $\Gamma_x(s\to s')\coloneqq\E_{\zeta\sim\Pi_x}\bigl[\sum_t
            d_{t+1}(\zeta)\1\{\zeta_t=s,\zeta_{t+1}=s'\}\bigr]$ (an operand's total occupation adds the edges
        from its other parents),
        \begin{align}
            \Gamma_x\!\bigl(s^{\mathrm{add}}_{z,p}\to s_{x_{\mathrm{op}},p}\bigr) \;=\;
            \tfrac12\,\Gamma_x\!\bigl(s^{\mathrm{add}}_{z,p}\bigr),
            \qquad
            \Gamma_x\!\bigl(s^{\mathrm{add}}_{z,p}\to s_{y_{\mathrm{op}},p}\bigr) \;=\;
            \tfrac12\,\Gamma_x\!\bigl(s^{\mathrm{add}}_{z,p}\bigr),
        \end{align}
        so the operand pair carries the full addition-state mass with no duplication.
    \item \textbf{Max Pooling.} For a pooled output $z = \max\{x_1,\dots,x_m\}$ with winner $k^\star$ and
        pooling state $s_{z,p}^{\max}$ (Section~\ref{ptnb:app:routing-skip}), the deterministic
        value-maximizing transition concentrates all mass on the winner: for every player label $p \in
            \{+,-\}$,
        \begin{align}
            \Gamma_x\!\bigl(s^{\max}_{z,p}\to s_{x_{k^\star},p}\bigr) \;=\;
            \Gamma_x\!\bigl(s_{z,p}^{\max}\bigr),
            \qquad
            \Gamma_x\!\bigl(s^{\max}_{z,p}\to s_{x_{k},p}\bigr) \;=\; 0 \text{ for } k \neq k^\star.
        \end{align}
\end{enumerate}
\hfill\LeanResult{ptnb:thm:ab-recovery}

[Probit dual of the soft gate]\label{ptnb:lem:noisy-gate-dual}
For every $z\in\RR$, the regularized maximization
\begin{align}\label{ptnb:eq:noisy-gate-objective}
    \max_{\pi \in [0,1]}\; \bigl\{\,\pi z \;+\; \mathcal{R}_\Phi(\pi)\,\bigr\}
\end{align}
admits the unique maximizer $\pi^\star = \Phi(z)$ and optimum value
\begin{align}\label{ptnb:eq:noisy-gate-optimum}
    z\,\Phi(z) + \phi(z) \;=\; \E_{\eta\sim\mathcal{N}(0,1)}\!\bigl[\max(z+\eta,\,0)\bigr].
\end{align}
\hfill\LeanResult{ptnb:lem:noisy-gate-dual}

[Softplus forward equivalence]\label{ptnb:thm:softplus-forward}\label{prop:softplus_game}
The entropy-regularized Stopping Game of~\eqref{ptnb:eq:softplus-soft-bellman} admits an SPNE whose
activation-state policy is the Gibbs policy~\eqref{ptnb:eq:softplus-policy}; it is unique on networks
without max-pooling nodes, since~\eqref{ptnb:eq:softplus-soft-bellman} is strictly concave (ties at
max-pooling states are resolved as in Section~\ref{ptnb:app:notation-identities}). Under this
equilibrium, at every activation state $s_{j,q}^{(l, \mathrm{act})}$,
\begin{align}\label{ptnb:eq:softplus-spne-tildes}
    \tilde V_p^{\pi^\star}\!\bigl(s_{j,q}^{(l, \mathrm{act})}\bigr)
    \;=\;
    a_{\mathrm{soft},j}^{(l, p \oplus q,\,\theta)},
    \qquad
    V_q^{\pi^\star}\!\bigl(s_{j,q}^{(l, \mathrm{act})}\bigr)
    \;=\;
    \mathrm{sp}_\theta\!\bigl(z_j^{(l)}\bigr),
\end{align}
where $a_{\mathrm{soft},j}^{(l, \pm,\,\theta)}$ are the Softplus-Decomposition activations of the
Softplus network with activation $\mathrm{sp}_\theta$, propagated
by~\eqref{ptnb:eq:split-pos}--\eqref{ptnb:eq:split-neg} from $a_{\mathrm{soft},k}^{(0,\pm,\theta)} = x_k^\pm$
with the decomposition function
\begin{align}\label{ptnb:eq:softplus-decomp}
    f_{\mathrm{soft}}^{\,\theta}(z^+, z^-) \;\coloneqq\; \bigl(\,\mathrm{sp}'_\theta(z^+ - z^-)\, z^+ +
    \theta\, \mathcal{H}_\theta(z^+ - z^-),\;\; \mathrm{sp}'_\theta(z^+ - z^-)\, z^-\,\bigr),
\end{align}
and $\mathcal{H}_\theta(z) \coloneqq \mathcal{H}(\mathrm{sp}'_\theta(z))$ the binary entropy of the
Gibbs weight.
\hfill\LeanResult{ptnb:thm:softplus-forward}

[Softplus gradient recovery]\label{ptnb:thm:softplus-gradient}
Under the SPNE of Theorem~\ref{ptnb:thm:softplus-forward} on the Softplus network with activation
$\mathrm{sp}_\theta$, the discounted occupation difference recovers the Softplus-network gradient
exactly as in Theorem~\ref{ptnb:thm:deriv-occ}:
\begin{align}
    \frac{\partial a_j^{(m)}}{\partial a_i^{(l)}}
    \;=\;
    \xi_{q,+}\Bigl(\Gamma_x\bigl(s_{i,+}^{(l, \mathrm{act})} \bigm| s\bigr) -
    \Gamma_x\bigl(s_{i,-}^{(l, \mathrm{act})} \bigm| s\bigr)\Bigr),
    \qquad s = s_{j,q}^{(m, \mathrm{act})},
\end{align}
with $\Gamma_x$ now driven by $\Pi_x^\theta$.
\hfill\LeanResult{ptnb:thm:softplus-gradient}

[Regional blindness of the input gradient]\label{prop:gradient_blindness}
Let $f$ be a \ac{relu} network as above, let $x_0$ be an input at which no pre-activation is exactly zero, and let $i$ be an input coordinate such that every path from input neuron $i$ to the output neuron passes through at least one neuron that is inactive at $x_0$. Then there is an open neighborhood $U \ni x_0$ with
\begin{equation*}
	\frac{\partial f}{\partial x_i} \equiv 0 \quad \text{on } U,
\end{equation*}
even if $f$ depends on $x_i$ elsewhere.
\hfill\LeanResult{prop:gradient_blindness}

[The canonical counterexample]\label{rem:sensitivity_counterexample}
Following \textcite{Sundararajan2017}, consider the one-dimensional \ac{relu} network
\begin{equation}
	f(x) = 1 - \relu(1 - x),
	\label{eq:ig_counterexample}
\end{equation}
and compare the input $x = 2$ against the baseline $x' = 0$. The prediction changes, $f(2) - f(0) = 1 - 0 = 1$, so the single feature is plainly relevant; yet $f$ is constant on $x \geq 1$, so the gradient at $x = 2$ --- and with it Input$\times$Gradient and every purely local backward rule --- assigns exactly zero attribution. The single hidden neuron is inactive at $x = 2$, and Proposition~\ref{prop:gradient_blindness} applies with $U = (1, \infty)$.

[Local sensitivities]\label{def:local_sensitivities}
For $s \in \{g, h\}$, $\sigma \in \{+, -\}$ and $0 \leq l \leq L$, the \emph{local sensitivities} of the split-pair at layer $l$ are the row vectors
\begin{equation*}
	\delta^{(l, \sigma, s)} \coloneqq \frac{\partial s^{(l)}}{\partial \act{l}{\sigma}} \in \RR^{1 \times d^{(l)}},
\end{equation*}
the derivatives of the stream outputs with respect to the positive and negative split activations of layer $l$. We further abbreviate the original-network sensitivity by $\delta^{(l)} \coloneqq \partial f^{(l)} / \partial \actl{l}$ and define the \emph{absolute weight product}
\begin{equation*}
	W_{\mathrm{abs}}^{[l]} \coloneqq \abs{\Wl{L}} \, \abs{\Wl{L-1}} \cdots \abs{\Wl{l+1}} \in \RR^{1 \times d^{(l)}},
	\qquad
	W_{\mathrm{abs}}^{[L]} \coloneqq \1^{\top},
\end{equation*}
where $\abs{\cdot}$ is taken entrywise. Since the attributed output is scalar, $W_{\mathrm{abs}}^{[l]}$ is a row vector, and its $i$-th entry sums the absolute weight products over \emph{all} paths from neuron $i$ of layer $l$ to the output --- active or not.

[Split backward recursions]\label{lem:split_backward_recursion}
With the activation masks $M^{(l,\pm)}$ of Proposition~\ref{prop:gradient_blindness}, extended by $M^{(L,+)}=I$ and $M^{(L,-)}=0$ for the affine readout, for every $0 \leq l < L$ and $s \in \{g, h\}$,
\begin{align}
	\delta^{(l, +, s)}
	&= \delta^{(l+1, +, s)} \bigl( M^{(l+1, +)} \Wsig{l+1}{+} + M^{(l+1, -)} \Wsig{l+1}{-} \bigr)
	+ \delta^{(l+1, -, s)} \, \Wsig{l+1}{-},
	\label{eq:delta_plus_recursion} \\
	\delta^{(l, -, s)}
	&= \delta^{(l+1, +, s)} \bigl( M^{(l+1, +)} \Wsig{l+1}{-} + M^{(l+1, -)} \Wsig{l+1}{+} \bigr)
	+ \delta^{(l+1, -, s)} \, \Wsig{l+1}{+},
	\label{eq:delta_minus_recursion}
\end{align}
with base case $\delta^{(L, +, g)} = \delta^{(L, -, h)} = \1^{\top}$ and $\delta^{(L, -, g)} = \delta^{(L, +, h)} = 0$.
\hfill\LeanResult{lem:split_backward_recursion}

[Sensitivity mass conservation]\label{prop:sensitivity_mass}
For every $0 \leq l \leq L$ and both streams $s \in \{g, h\}$,
\begin{equation}
	\delta^{(l, +, s)} + \delta^{(l, -, s)} = W_{\mathrm{abs}}^{[l]}.
	\label{eq:mass_conservation}
\end{equation}
\hfill\LeanResult{prop:sensitivity_mass}

[Backward invariant]\label{cor:backward_invariant}
For every $0 \leq l \leq L$,
\begin{equation}
	\delta^{(l, +, g)} - \delta^{(l, +, h)} = \delta^{(l)} = -\bigl( \delta^{(l, -, g)} - \delta^{(l, -, h)} \bigr),
	\quad \text{hence} \quad
	\bigl( \delta^{(l,+,g)} - \delta^{(l,-,g)} \bigr) - \bigl( \delta^{(l,+,h)} - \delta^{(l,-,h)} \bigr) = 2\,\delta^{(l)}.
	\label{eq:backward_invariant}
\end{equation}
\hfill\LeanResult{cor:backward_invariant}

[The counterexample, revisited]\label{rem:counterexample_split}
Split the network \eqref{eq:ig_counterexample} with the balanced input split $\act{0}{\pm} = \pm x/2$. A short computation along Section~\ref{sec:dc_splitting_relu} gives, for $x > 1$,
\begin{equation*}
	g(x) = \frac{x}{2} + 1, \qquad h(x) = \frac{x}{2}, \qquad g(x) - h(x) = 1 = f(x),
\end{equation*}
so at $x = 2$ both stream gradients equal $\tfrac{1}{2} \neq 0$ while $f'(2) = 0$: the split representation \emph{sees} that the feature matters --- consistent with $f(2) \neq f(0)$ --- and encodes the vanishing of $f'$ as the cancellation $\tfrac{1}{2} - \tfrac{1}{2}$. For this example and the baseline $x'=0$, the pair of head gradients therefore supplies a nonzero signal even though the output gradient vanishes. This example does not establish the sensitivity axiom of Definition~\ref{def:sensitivity} for a general attribution rule or baseline. The attribution methods of the following sections differ in how they turn this pair-valued signal into a scalar map; the shifted combinations of Section~\ref{sec:split_grad} keep the two streams from cancelling exactly, and in this example assign the feature a strictly positive attribution for every shift parameter $\alpha < \tfrac{1}{2}$.

[Shifted local sensitivities]\label{def:shifted_sensitivities}
Fix shift parameters $\alpha^{(l)} \in [0, \tfrac{1}{2}]$. For $s \in \{g, h\}$ define, backward from layer $L$, intermediate sensitivities $\delta_{\mathrm{int}}^{(l, \pm, s)}$ by evaluating the recursions \eqref{eq:delta_plus_recursion}--\eqref{eq:delta_minus_recursion} (respectively the base case of Lemma~\ref{lem:split_backward_recursion} at $l = L$) with the already-shifted sensitivities of the subsequent layer, and set
\begin{equation}
	\delta_{\mathrm{shift}}^{(l, \pm, s)}
	\coloneqq \delta_{\mathrm{int}}^{(l, \pm, s)} - \alpha^{(l)} \bigl( \delta_{\mathrm{int}}^{(l, +, s)} + \delta_{\mathrm{int}}^{(l, -, s)} \bigr),
	\qquad
	\delta_{\mathrm{shift}}^{(l, s)} \coloneqq \frac{\delta_{\mathrm{shift}}^{(l, +, s)} - \delta_{\mathrm{shift}}^{(l, -, s)}}{2}.
	\label{eq:shift_definition}
\end{equation}

[SplitCAM]\label{def:splitcam}
For a layer $l$ of the decomposed model, a stream $s \in \{g, h\}$ and a sign $\sigma \in \{+, -\}$, the SplitCAM attribution maps are
\begin{align}
	\text{SplitCAM}^{(l, \sigma, s)} &\coloneqq \sum_{c} \delta_{\mathrm{shift}}^{(l, \sigma, s)}\big\vert_c \odot \act{l}{\sigma}_c,
	\label{eq:splitcam_stream} \\
	\text{SplitCAM}^{(l, s)} &\coloneqq \sum_{c} \delta_{\mathrm{shift}}^{(l, s)}\big\vert_c \odot \actl{l}_c,
	\label{eq:splitcam_combined}
\end{align}
where $\act{l}{\sigma}_c$ denotes the channel-$c$ activation map of the $\sigma$-stream, $\actl{l}_c = \act{l}{+}_c - \act{l}{-}_c$ the reconstructed original activation map, and $\cdot\vert_c$ the restriction of a sensitivity tensor to channel $c$.

[Combined SplitLRP map]\label{def:splitlrp_combined}
The SplitLRP attribution at layer $l$ is the pair $\bigl(R^{(l,+)}, R^{(l,-)}\bigr)$; the \emph{combined} map is
\begin{equation}
	R^{(l, \mathrm{comb})} \coloneqq R^{(l, +)} - R^{(l, -)}.
	\label{eq:splitlrp_combined}
\end{equation}

[SplitGrad]\label{def:splitgrad}
For a layer $l$ and stream $s \in \{g, h\}$, the SplitGrad attribution map is the channel mean of the combined shifted sensitivity,
\begin{equation}
	\text{SplitGrad}^{(l, s)} \coloneqq \frac{1}{C^{(l)}} \sum_{c = 1}^{C^{(l)}} \delta_{\mathrm{shift}}^{(l, s)}\big\vert_c,
	\label{eq:splitgrad}
\end{equation}
where $C^{(l)}$ is the number of channels of layer $l$; the default configuration reads the $g$-stream, with forward and backward stabilization exactly as in Section~\ref{sec:split_cam}.

[DCINN and difference-of-monotone models]\label{def:dcinn}
Fix a base architecture. A \emph{DCINN} (in short: DIC model) is the function
\begin{equation*}
	f_{\mathrm{DIC}} \coloneqq g - h,
\end{equation*}
where $g$ and $h$ are two \acp{icnn} of the base architecture with independent parameters, trained \emph{jointly} by standard empirical risk minimization on the difference. The \emph{DM model} is defined analogously with both streams monotone networks. The \emph{inverted-input} variants DICIN and DMIN feed the $h$-stream the complemented input $\1 - x$ (for inputs normalized to $[0,1]^d$) instead of $x$.

[Representation by maxima of posynomials]\label{prop:posynomial_representation}
A monotone rank-$k$ Maxout multiplication network with non-negative intermediate quantities represents the maximum of finitely many posynomials in its non-negative input variables, and is monotone on the non-negative orthant. This representation does not imply ordinary convexity: the positive-coefficient monomial $xy$ is a counterexample. Allowing signed input-incident affine maps likewise supplies no general input-convexity guarantee in the presence of multiplication.
\hfill\LeanResult{prop:posynomial_representation}

[Monotone split of multiplicative \ac{relu} networks]\label{thm:multiplicative_split}
Let $N$ be a (residual) \ac{relu} network containing linear, convolutional, maximum, matrix-product, and Hadamard-product components. Then, on non-negative split-input variables, $N$ has two \emph{monotone} rank-$2$ Maxout multiplication networks $N^{+}$ and $N^{-}$ satisfying
\begin{equation*}
	N(x) = N^{+}(x^+,x^-) - N^{-}(x^+,x^-), \qquad x=x^+-x^-,\quad x^\pm\ge0,
\end{equation*}
Each component is monotone as a function of its non-negative split inputs and is representable there by a finite maximum of posynomials. This gives a difference-of-monotone representation; it does not establish a difference-of-convex representation in the original inputs. If the number of expanded monomials per multiplication neuron is uniformly bounded, the sizes of the split networks are linear in the size of $N$.
\hfill\LeanResult{thm:multiplicative_split}

[Legendre--Fenchel transform of KL divergence]\label{ptnb:lem:kl-legendre-fenchel}
Let $\mathcal{X}$ be a finite set, $\bar\pi \in \Delta(\mathcal{X})$ a reference distribution with
full support on $\mathcal{X}$, and $r : \mathcal{X} \to \RR$ a real-valued payoff. The
KL-regularized linear maximization
\begin{align}\label{ptnb:eq:kl-lf-objective}
    F(r;\bar\pi) \;\coloneqq\; \max_{\pi \in \Delta(\mathcal{X})}
    \Bigl\{ \E_\pi[r] \;-\; \mathrm{KL}(\pi \,\|\, \bar\pi) \Bigr\}
\end{align}
has the following optimizer and optimum:
\begin{align}\label{ptnb:eq:kl-lf-optimizer}
    \pi_r^\star(x) \;=\; \frac{\bar\pi(x)\,\exp\!\bigl(r(x)\bigr)}{Z(r;\bar\pi)},
    \qquad
    F(r;\bar\pi) \;=\; \log Z(r;\bar\pi) \;=\; \log\!\sum_{x \in \mathcal{X}}
    \bar\pi(x)\,\exp\!\bigl(r(x)\bigr).
\end{align}
\hfill\LeanResult{ptnb:lem:kl-legendre-fenchel}

[Value-side optimal policy]\label{ptnb:prop:attn-value-policy}
If $Z_{t,d}^\kappa > 0$, the unique optimizer of~\eqref{ptnb:eq:attn-value-routing} is
\begin{align}\label{ptnb:eq:attn-value-policy}
    \pi_{t,d,\kappa}^\star(k)
    \;=\;
    \frac{\bar\pi_t(k)\, \tilde{v}_{k,d}^\kappa}{Z_{t,d}^\kappa},
\end{align}
with active-player value $V_p(s_{(t,d),p,\kappa}^{(\mathrm{att},\,\mathrm{O},\,\mathrm{lin})}) =
    \ell(Z_{t,d}^\kappa)$ and inactive-player value
$V_{p'}(s_{(t,d),p,\kappa}^{(\mathrm{att},\,\mathrm{O},\,\mathrm{lin})}) = -\infty$ as in
Definition~\ref{ptnb:def:routing-recursion}. If $Z_{t,d}^\kappa = 0$, no key contributes mass on stream
$\kappa$ and $V_p(s_{(t,d),p,\kappa}^{(\mathrm{att},\,\mathrm{O},\,\mathrm{lin})}) = -\infty$.
\hfill\LeanResult{ptnb:prop:attn-value-policy}

[$\alpha\beta$-\ac{lrp} recovery for attention]\label{ptnb:thm:attn-ab-recovery}\label{thm:attention_ab_recovery}
For signed inputs $X$, under the SPNE of \S\ref{ptnb:app:attention-state-space} with reference
$\bar\pi_t = A_{t,\cdot}$ and the trajectory discount of~\eqref{ptnb:eq:routing-edge-discount}
restricted to the (sole) sign-oracle split at $s^{(\mathrm{att},\,\mathrm{O},\,\mathrm{act})}$, the
per-input-neuron player-difference $\Gamma^{X}_{k,e}$ from~\eqref{ptnb:eq:attn-Gamma-X} satisfies
\begin{align}\label{ptnb:eq:attn-ab-recovery}
    \Gamma^{X}_{k,e}
    \;=\;
    \sum_{t,d} \left(
    \alpha\, \frac{A_{t,k}\, [X_{k,e} W_{v,e,d}]^+}{Z_{t,d}^+}
    \;-\;
    \beta\, \frac{A_{t,k}\, [X_{k,e} W_{v,e,d}]^-}{Z_{t,d}^-}
    \right) \Gamma^{O}_{t,d},
\end{align}
where the per-output-entry input difference is
\begin{align}\label{ptnb:eq:attn-Gamma-O}
    \Gamma^{O}_{t,d} \;\coloneqq\;
    \Gamma_x\!\bigl(s_{t,d,+}^{(\mathrm{att},\,\mathrm{O},\,\mathrm{act})}\bigr) \;-\;
    \Gamma_x\!\bigl(s_{t,d,-}^{(\mathrm{att},\,\mathrm{O},\,\mathrm{act})}\bigr),
\end{align}
with $\Gamma^{O}_{t,d} = R^{O}_{t,d}$ by inductive hypothesis from the surrounding recursion, for
the seed $R^{(L)}_u = 1$ (for the seed $f(x)$ every relevance equals $f(x)$ times the corresponding
$\Gamma$, as in Theorem~\ref{ptnb:thm:ab-recovery}). The right-hand side is exactly the target
rule~\eqref{ptnb:eq:attn-target-input}, hence $\Gamma^{X}_{k,e} = R^{X}_{k,e}$. Aggregating over $e$ and
the bias node at fixed $(k,d)$ collects the relevance routed through the Value entry $v_{k,d}$:
\begin{align}\label{ptnb:eq:attn-Gamma-V-corollary}
    \Gamma^{\mathrm{val}}_{k,d}
    \;=\;
    \sum_t \left( \alpha\, \frac{A_{t,k}\, \tilde{v}_{k,d}^+}{Z_{t,d}^+} \;-\; \beta\, \frac{A_{t,k}\,
    \tilde{v}_{k,d}^-}{Z_{t,d}^-} \right) \Gamma^{O}_{t,d}
    \;=\; R^{\mathrm{val}}_{k,d},
\end{align}
recovering the per-Value-entry formula~\eqref{ptnb:eq:attn-target-rule}.
\hfill\LeanResult{ptnb:thm:attn-ab-recovery}

[Chain rule]\label{ptnb:lem:bc-chain-rule}
For every $l \in \{0, 1, \ldots, L\}$, the Bhattacharyya coefficient of the prefix distributions
factorizes along trajectories:
\begin{align}\label{ptnb:eq:bc-chain-rule}
    \mathrm{BC}\!\bigl(\Pi^{(l)}_A,\, \Pi^{(l)}_B\bigr) \;=\; \sum_{(\zeta_L, \ldots, \zeta_l)}
    \mathbf{1}\{\zeta_L = s_0\} \prod_{k=l+1}^{L} \widetilde{T}^{(k)}(\zeta_k, \zeta_{k-1}).
\end{align}
\hfill\LeanResult{ptnb:lem:bc-chain-rule}

[Monotonicity]\label{ptnb:lem:bc-monotone}
Let $\mathrm{BC}^{(l)} \coloneqq \mathrm{BC}(\Pi^{(l)}_A, \Pi^{(l)}_B)$.  Then $\mathrm{BC}^{(l)}$
is monotonically non-increasing as $l$ decreases from $L$ to $0$:
\begin{align}
    1 \;=\; \mathrm{BC}^{(L)} \;\geq\; \mathrm{BC}^{(L-1)} \;\geq\; \cdots \;\geq\; \mathrm{BC}^{(0)}
    \;\geq\; 0.
\end{align}
Equivalently, the squared Hellinger distance $\mathrm{H}^{2}_{(l)} = 1 - \mathrm{BC}^{(l)}$ is
monotonically non-decreasing.
\hfill\LeanResult{ptnb:lem:bc-monotone}

[Backward pass correctness]\label{ptnb:lem:hellinger-backward-correctness}
Algorithm~\ref{ptnb:alg:hellinger} computes $g^{(l)}$, hence $\mathrm{BC}^{(l)}$, $\mathrm{H}^{(l)}$,
and $\mathrm{H}^2(s)$ correctly for every $l$ and $s$.  In particular,
\begin{align}
    \sum_{s \in \mathcal{S}^{(0)}_+} \mathrm{H}^2(s) \;=\; \mathrm{H}^{2}_{(0)}.
\end{align}
\hfill\LeanResult{ptnb:lem:hellinger-backward-correctness}

[Per-pixel decomposition]\label{ptnb:thm:per-pixel}
Let $\mathrm{H}^2 \coloneqq \mathrm{H}^2\!\bigl(\Pi^{(0)}_A,\, \Pi^{(0)}_B\bigr)$.  For $s \in
    \mathcal{S}^{(0)}_+$, define
\begin{align}\label{ptnb:eq:per-pixel-h2}
    \mathrm{H}^2(s) \;\coloneqq\; \tfrac{1}{2}\bigl(m^{(0)}_A(s) + m^{(0)}_B(s)\bigr) \;-\; g^{(0)}(s),
\end{align}
where $g^{(0)}(s)$ is the cumulative $\widetilde{T}$-mass at $s$.  Then:
\begin{enumerate}
    \item[(i)] $\mathrm{H}^2(s) \geq 0$ for every $s \in \mathcal{S}^{(0)}_+$.
    \item[(ii)]
        \begin{align}\label{ptnb:eq:per-pixel-sum}
            \mathrm{H}^2 \;=\; \sum_{s \in \mathcal{S}^{(0)}_+} \mathrm{H}^2(s).
        \end{align}
    \item[(iii)]
        \begin{align}\label{ptnb:eq:ordinary-h2}
            \mathrm{H}^2_{\mathrm{ord}} \;\coloneqq\; \sum_{s \in \mathcal{S}^{(0)}} \mathrm{H}^2(s) \;=\;
            \mathrm{H}^2 - \mathrm{H}^2(\dagger)
        \end{align}
\end{enumerate}
\hfill\LeanResult{ptnb:thm:per-pixel}

[Conditioned-survival trajectory law and conditioned Hellinger distance]\label{ptnb:thm:conditioned-survival}
Let $\mathsf{Surv} \coloneqq \{(\zeta_L,\ldots,\zeta_0) : \zeta_0 \in \mathcal{S}^{(0)}\}$ be the
event, in the trajectory space $\prod_{l=0}^{L} \mathcal{S}^{(l)}_+$, that the backward trajectory
ends in an ordinary input-layer state — equivalently, the event that the trajectory never enters
the cemetery~$\dagger$.  For each model $M \in \{A,B\}$ define the survival function
\begin{align}\label{ptnb:eq:survival-function}
    \psi_M^{(l)}(s)
    \;\coloneqq\;
    \mathbb{P}_M(\mathsf{Surv} \mid \zeta_l = s),
    \qquad s \in \mathcal{S}^{(l)}_+, \;\; l \in \{0,\ldots,L\}.
\end{align}
Then:
\begin{enumerate}
    \item[(i)] The boundary and recursion are
        \begin{align}\label{ptnb:eq:survival-boundary}
            \psi_M^{(0)}(s) = 1 \;\; \text{for } s \in \mathcal{S}^{(0)},
            \qquad
            \psi_M^{(0)}(\dagger) = 0,
        \end{align}
        and for every $l \ge 1$,
        \begin{align}\label{ptnb:eq:survival-recursion}
            \psi_M^{(l)}(s)
            \;=\;
            \sum_{s' \in \mathcal{S}^{(l-1)}_+} T_M^{(l)}(s \to s')\, \psi_M^{(l-1)}(s')
            \;=\;
            \sum_{s' \in \mathcal{S}^{(l-1)}} T_M^{(l)}(s \to s')\, \psi_M^{(l-1)}(s').
        \end{align}
        In particular,
        \begin{align}\label{ptnb:eq:survival-mass}
            Z_M \;\coloneqq\; \mathbb{P}_M(\mathsf{Surv}) \;=\; \psi_M^{(L)}(s_0) \;=\; \sum_{s \in
            \mathcal{S}^{(0)}} m_M^{(0)}(s) \;=\; 1 - m_M^{(0)}(\dagger).
        \end{align}
    \item[(ii)] Assume $Z_M > 0$.  For every ordinary state $s \in \mathcal{S}^{(l)}$ with $\psi_M^{(l)}(s) >
            0$, define the conditioned kernel on ordinary states by
        \begin{align}\label{ptnb:eq:conditioned-kernel}
            T_{M,\mathrm{surv}}^{(l)}(s \to s')
            \;\coloneqq\;
            \frac{T_M^{(l)}(s \to s')\, \psi_M^{(l-1)}(s')}{\psi_M^{(l)}(s)},
            \qquad s' \in \mathcal{S}^{(l-1)}.
        \end{align}
        Then $T_{M,\mathrm{surv}}^{(l)}(s \to \cdot)$ is row-stochastic on $\mathcal{S}^{(l-1)}$, and the
        conditional trajectory distribution $\Pi_{M,\mathrm{surv}} \coloneqq \Pi_M(\,\cdot \mid
            \mathsf{Surv}\,)$ factorizes as the layered Markov law
        \begin{align}\label{ptnb:eq:conditioned-path-measure}
            \Pi_{M,\mathrm{surv}}(\zeta_L,\ldots,\zeta_0)
            = \mathbf{1}\{\zeta_L = s_0\} \prod_{k=1}^{L} T_{M,\mathrm{surv}}^{(k)}(\zeta_k \to \zeta_{k-1}),
            \qquad (\zeta_L,\ldots,\zeta_0) \in \mathsf{Surv}.
        \end{align}
        Its layer-$l$ marginals satisfy
        \begin{align}\label{ptnb:eq:conditioned-alpha}
            m_{M,\mathrm{surv}}^{(l)}(s)
            \;=\;
            \frac{m_M^{(l)}(s)\, \psi_M^{(l)}(s)}{Z_M},
            \qquad s \in \mathcal{S}^{(l)}.
        \end{align}
    \item[(iii)] Define the conditioned geometric-mean kernel
        \begin{align}\label{ptnb:eq:conditioned-geom-kernel}
            \widetilde{T}_{\mathrm{surv}}^{(l)}(s,s')
            \coloneqq \sqrt{T_{A,\mathrm{surv}}^{(l)}(s \to s')\, T_{B,\mathrm{surv}}^{(l)}(s \to s')}
            = \frac{\widetilde{T}^{(l)}(s,s')\, \sqrt{\psi_A^{(l-1)}(s')\,
            \psi_B^{(l-1)}(s')}}{\sqrt{\psi_A^{(l)}(s)\, \psi_B^{(l)}(s)}}.
        \end{align}
        The Bhattacharyya coefficient of the conditioned trajectory laws is
        \begin{align}\label{ptnb:eq:conditioned-bc-kernel}
            \mathrm{BC}\!\bigl(\Pi_{A,\mathrm{surv}}, \Pi_{B,\mathrm{surv}}\bigr)
            \;=\;
            \sum_{(\zeta_L,\ldots,\zeta_0) \in \mathsf{Surv}}
            \mathbf{1}\{\zeta_L = s_0\}
            \prod_{k=1}^{L} \widetilde{T}_{\mathrm{surv}}^{(k)}(\zeta_k, \zeta_{k-1}),
        \end{align}
        so it is computed by the same Hellinger pass (Algorithm~\ref{ptnb:alg:hellinger}), but on the
        ordinary-state graph with the conditioned kernel.
    \item[(iv)] Let
        \begin{align}\label{ptnb:eq:ordinary-bc}
            \mathrm{BC}_{\mathrm{ord}}^{(0)}
            \;\coloneqq\;
            \sum_{s \in \mathcal{S}^{(0)}} g^{(0)}(s)
            \;=\;
            \sum_{(\zeta_L,\ldots,\zeta_0) \in \mathsf{Surv}} \sqrt{\Pi_A(\zeta_L,\ldots,\zeta_0)\,
            \Pi_B(\zeta_L,\ldots,\zeta_0)}.
        \end{align}
        Then
        \begin{align}\label{ptnb:eq:conditioned-bc-posthoc}
            \mathrm{BC}\!\bigl(\Pi_{A,\mathrm{surv}}, \Pi_{B,\mathrm{surv}}\bigr)
            \;=\;
            \frac{\mathrm{BC}_{\mathrm{ord}}^{(0)}}{\sqrt{Z_A Z_B}},
        \end{align}
        and the conditioned-survival Hellinger distance is
        \begin{align}\label{ptnb:eq:conditioned-h2}
            \mathrm{H}_{\mathrm{surv}}^2
            \;\coloneqq\;
            \mathrm{H}^2\!\bigl(\Pi_{A,\mathrm{surv}}, \Pi_{B,\mathrm{surv}}\bigr)
            \;=\;
            1 - \frac{\mathrm{BC}_{\mathrm{ord}}^{(0)}}{\sqrt{Z_A Z_B}}.
        \end{align}
\end{enumerate}
\hfill\LeanResult{ptnb:thm:conditioned-survival}

[Randomization in the Stopping Game]\label{ptnb:thm:rand-adf}\label{thm:rand_stopping}
$\mathbb{E}_B\bigl[\mathrm{BC}^{(0)}_{\mathrm{ord}}(\Pi_A, \Pi_B)\bigr] \leq \eta^{N}$.  Hence, for
every $z > 0$, the conditioned-survival distance of Theorem~\ref{ptnb:thm:conditioned-survival}
satisfies $\mathbb{E}_B\bigl[\mathrm{H}^2_{\mathrm{surv}}\,\1\{Z_A Z_B \geq z\}\bigr] \geq
    \mathbb{P}_B(Z_A Z_B \geq z) - \eta^{N}/\sqrt{z}$, while the plain distance is $\mathrm{H}^2 = 1 -
    \mathrm{BC}^{(0)}_{\mathrm{ord}} - g^{(0)}(\dagger)$.
\hfill\LeanResult{ptnb:thm:rand-adf}

[Randomization in the Routing Game]\label{ptnb:thm:rand-routing}\label{thm:rand_routing}
Under the same setup without the alive-set assumption, take the \ac{rg} kernel at temperature $\tau
    > 0$ and assume that for every $l \geq l^*$ each state alive in both models has row mass
$\sum_{s'}\widetilde{T}^{(l)}(s, s') \leq \bar{b}$ for some $0 \leq \bar{b} < 1$.  Then
$\mathrm{BC}^{(0)}_{\mathrm{ord}}(\Pi_A, \Pi_B) \leq \bar{b}^{N}$.
\hfill\LeanResult{ptnb:thm:rand-routing}
